def compute(mins, shrinks, grows, target):
    size=sum(mins); fgs=sum(grows); fss=sum(m*s for m,s in zip(mins,shrinks)); fsz=sum(m for m,s in zip(mins,shrinks) if s)
    extra=target-size
    out=[]
