        q=abs(a)//abs(b)
        return q if (a>=0)==(b>0) else -q
    if extra>=0:
        for m,g in zip(mins,grows):
            add=tdiv(extra*g,max(fgs,1)); extra-=add; fgs-=g; out.append(m+add)
    elif fsz+extra>=0:
        for m,s in zip(mins,shrinks):
            add=tdiv(extra*m*s,max(fss,1)); extra-=add; fss-=s*m; out.append(m+add)
    else:
        extra+=fsz; size-=fsz
        for m,s in zip(mins,shrinks):
            if s: out.append(0); continue
