def run(argv, w=80, h=24, inputs=(), total=2.0, answer_dsr=True, dsr_pos=(1,1)):
    pid, fd = pty.fork()
    if pid == 0:
        os.execv(argv[0], argv)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', h, w, 0, 0))
