#include <vector>

namespace jt {

class Json {
 public:
  enum class Type { Null, Boolean, Integer, Unsigned, Float, String, Array, Object };

  Json() = default;
  static Json MakeArray() { Json j; j.type_ = Type::Array; return j; }
  static Json MakeObject() { Json j; j.type_ = Type::Object; return j; }

  Type type() const { return type_; }
  bool is_null() const { return type_ == Type::Null; }
  bool is_boolean() const { return type_ == Type::Boolean; }
  bool is_number() const {
    return type_ == Type::Integer || type_ == Type::Unsigned || type_ == Type::Float;
  }
  bool is_string() const { return type_ == Type::String; }
  bool is_array() const { return type_ == Type::Array; }
  bool is_object() const { return type_ == Type::Object; }

  bool boolean_value = false;
  int64_t integer_value = 0;
  uint64_t unsigned_value = 0;
  double float_value = 0.0;
  std::string string_value;
  std::vector<Json> array_value;
  std::map<std::string, Json> object_value;

  void SetType(Type t) { type_ = t; }

  size_t size() const {
    if (is_array()) return array_value.size();
    if (is_object()) return object_value.size();
    if (is_null()) return 0;
    return 1;
  }

