namespace jt {

namespace {

enum class Token {
  uninitialized,
  literal_true,
  literal_false,
  literal_null,
  value_string,
  value_unsigned,
  value_integer,
  value_float,
  begin_array,
  begin_object,
  end_array,
  end_object,
  name_separator,
  value_separator,
  parse_error,
  end_of_input,
  literal_or_value
};

const char* TokenName(Token t) {
  switch (t) {
    case Token::uninitialized: return "<uninitialized>";
    case Token::literal_true: return "true literal";
    case Token::literal_false: return "false literal";
    case Token::literal_null: return "null literal";
    case Token::value_string: return "string literal";
    case Token::value_unsigned:
    case Token::value_integer:
    case Token::value_float: return "number literal";
    case Token::begin_array: return "'['";
    case Token::begin_object: return "'{'";
    case Token::end_array: return "']'";
    case Token::end_object: return "'}'";
    case Token::name_separator: return "':'";
    case Token::value_separator: return "','";
    case Token::parse_error: return "<parse error>";
    case Token::end_of_input: return "end of input";
    case Token::literal_or_value: return "'[', '{', or a literal";
  }
  return "unknown token";
}

constexpr int kEOF = -1;

class Lexer {
 public:
  explicit Lexer(const std::string& in) : input_(in) {}

  int Get() {
    ++chars_read_total_;
    ++chars_read_current_line_;
    if (next_unget_) {
      next_unget_ = false;
    } else {
      current_ = pos_ < input_.size()
                     ? static_cast<unsigned char>(input_[pos_++])
                     : kEOF;
    }
    if (current_ != kEOF) {
      token_string_.push_back(static_cast<char>(current_));
    }
    if (current_ == '\n') {
      ++lines_read_;
      chars_read_current_line_ = 0;
    }
    return current_;
  }

  void Unget() {
    next_unget_ = true;
    --chars_read_total_;
    if (chars_read_current_line_ == 0) {
      if (lines_read_ > 0) {
        --lines_read_;
      }
    } else {
      --chars_read_current_line_;
    }
    if (current_ != kEOF && !token_string_.empty()) {
      token_string_.pop_back();
    }
  }

  void Reset() {
    token_buffer_.clear();
    token_string_.clear();
    if (current_ != kEOF) {
      token_string_.push_back(static_cast<char>(current_));
    }
  }

  void Add(int c) { token_buffer_.push_back(static_cast<char>(c)); }

  std::string TokenString() const {
    std::string result;
    for (char c : token_string_) {
      unsigned char uc = static_cast<unsigned char>(c);
      if (uc <= 0x1F) {
        char cs[16];
        std::snprintf(cs, sizeof(cs), "<U+%.4X>", uc);
        result += cs;
      } else {
        result.push_back(c);
      }
    }
    return result;
  }

  bool SkipBom() {
    if (Get() == 0xEF) {
      return Get() == 0xBB && Get() == 0xBF;
    }
    Unget();
    return true;
  }

  void SkipWhitespace() {
    do {
      Get();
    } while (current_ == ' ' || current_ == '\t' || current_ == '\n' ||
             current_ == '\r');
  }

  Token ScanLiteral(const char* text, size_t length, Token type) {
    for (size_t i = 1; i < length; ++i) {
      if (Get() != static_cast<unsigned char>(text[i])) {
        error_message_ = "invalid literal";
        return Token::parse_error;
      }
    }
    return type;
  }

  int GetCodepoint() {
    int codepoint = 0;
    for (int factor : {12, 8, 4, 0}) {
      Get();
      if (current_ >= '0' && current_ <= '9') {
        codepoint += (current_ - 0x30) << factor;
      } else if (current_ >= 'A' && current_ <= 'F') {
        codepoint += (current_ - 0x37) << factor;
      } else if (current_ >= 'a' && current_ <= 'f') {
        codepoint += (current_ - 0x57) << factor;
      } else {
        return -1;
      }
    }
    return codepoint;
  }

  bool NextByteInRange(std::initializer_list<int> ranges) {
    Add(current_);
    for (auto it = ranges.begin(); it != ranges.end(); ++it) {
      Get();
      int lo = *it;
      ++it;
      int hi = *it;
      if (lo <= current_ && current_ <= hi) {
        Add(current_);
      } else {
        error_message_ = "invalid string: ill-formed UTF-8 byte";
        return false;
      }
    }
    return true;
  }

  void AddCodepoint(int codepoint) {
    if (codepoint < 0x80) {
      Add(codepoint);
    } else if (codepoint <= 0x7FF) {
      Add(0xC0 | (codepoint >> 6));
      Add(0x80 | (codepoint & 0x3F));
    } else if (codepoint <= 0xFFFF) {
      Add(0xE0 | (codepoint >> 12));
      Add(0x80 | ((codepoint >> 6) & 0x3F));
      Add(0x80 | (codepoint & 0x3F));
    } else {
      Add(0xF0 | (codepoint >> 18));
      Add(0x80 | ((codepoint >> 12) & 0x3F));
      Add(0x80 | ((codepoint >> 6) & 0x3F));
      Add(0x80 | (codepoint & 0x3F));
    }
  }

  Token ScanString() {
    Reset();
    while (true) {
      int c = Get();
      if (c == kEOF) {
        error_message_ = "invalid string: missing closing quote";
        return Token::parse_error;
      }
      if (c == '"') {
        return Token::value_string;
      }
      if (c == '\\') {
        switch (Get()) {
          case '"': Add('"'); break;
          case '\\': Add('\\'); break;
          case '/': Add('/'); break;
          case 'b': Add('\b'); break;
          case 'f': Add('\f'); break;
          case 'n': Add('\n'); break;
          case 'r': Add('\r'); break;
          case 't': Add('\t'); break;
          case 'u': {
            const int codepoint1 = GetCodepoint();
            int codepoint = codepoint1;
            if (codepoint1 == -1) {
              error_message_ =
                  "invalid string: '\\u' must be followed by 4 hex digits";
              return Token::parse_error;
            }
            if (0xD800 <= codepoint1 && codepoint1 <= 0xDBFF) {
              if (Get() == '\\' && Get() == 'u') {
                const int codepoint2 = GetCodepoint();
                if (codepoint2 == -1) {
                  error_message_ =
                      "invalid string: '\\u' must be followed by 4 hex digits";
                  return Token::parse_error;
                }
                if (0xDC00 <= codepoint2 && codepoint2 <= 0xDFFF) {
                  codepoint = ((codepoint1 << 10) + codepoint2 - 0x35FDC00);
                } else {
                  error_message_ =
                      "invalid string: surrogate U+D800..U+DBFF must be "
                      "followed by U+DC00..U+DFFF";
                  return Token::parse_error;
                }
              } else {
                error_message_ =
                    "invalid string: surrogate U+D800..U+DBFF must be "
                    "followed by U+DC00..U+DFFF";
                return Token::parse_error;
              }
            } else if (0xDC00 <= codepoint1 && codepoint1 <= 0xDFFF) {
              error_message_ =
                  "invalid string: surrogate U+DC00..U+DFFF must follow "
                  "U+D800..U+DBFF";
              return Token::parse_error;
            }
            AddCodepoint(codepoint);
            break;
          }
          default:
            error_message_ =
                "invalid string: forbidden character after backslash";
            return Token::parse_error;
        }
        continue;
      }
      if (c <= 0x1F) {
        static const char* names[32] = {
            "NUL", "SOH", "STX", "ETX", "EOT", "ENQ", "ACK", "BEL",
            "BS",  "HT",  "LF",  "VT",  "FF",  "CR",  "SO",  "SI",
            "DLE", "DC1", "DC2", "DC3", "DC4", "NAK", "SYN", "ETB",
            "CAN", "EM",  "SUB", "ESC", "FS",  "GS",  "RS",  "US"};
        char buf[160];
        const char* extra = "";
        switch (c) {
          case 0x08: extra = " or \\b"; break;
          case 0x09: extra = " or \\t"; break;
          case 0x0A: extra = " or \\n"; break;
          case 0x0C: extra = " or \\f"; break;
          case 0x0D: extra = " or \\r"; break;
          default: break;
        }
        std::snprintf(buf, sizeof(buf),
                      "invalid string: control character U+%.4X (%s) must be "
                      "escaped to \\u%.4X%s",
                      c, names[c], c, extra);
        error_message_ = buf;
        return Token::parse_error;
      }
      if (c <= 0x7F) {
        Add(c);
        continue;
      }
      bool ok = true;
      if (c >= 0xC2 && c <= 0xDF) {
        ok = NextByteInRange({0x80, 0xBF});
      } else if (c == 0xE0) {
        ok = NextByteInRange({0xA0, 0xBF, 0x80, 0xBF});
      } else if ((c >= 0xE1 && c <= 0xEC) || c == 0xEE || c == 0xEF) {
        ok = NextByteInRange({0x80, 0xBF, 0x80, 0xBF});
      } else if (c == 0xED) {
        ok = NextByteInRange({0x80, 0x9F, 0x80, 0xBF});
      } else if (c == 0xF0) {
        ok = NextByteInRange({0x90, 0xBF, 0x80, 0xBF, 0x80, 0xBF});
      } else if (c >= 0xF1 && c <= 0xF3) {
        ok = NextByteInRange({0x80, 0xBF, 0x80, 0xBF, 0x80, 0xBF});
      } else if (c == 0xF4) {
        ok = NextByteInRange({0x80, 0x8F, 0x80, 0xBF, 0x80, 0xBF});
      } else {
        error_message_ = "invalid string: ill-formed UTF-8 byte";
        return Token::parse_error;
      }
      if (!ok) {
        return Token::parse_error;
      }
    }
  }

  static bool IsDigit(int c) { return c >= '0' && c <= '9'; }

  Token ScanNumber() {
    Reset();
    Token number_type = Token::value_unsigned;
    int state = 0;
    // States: 0=start 1=minus 2=zero 3=any1 4=decimal1 5=decimal2
    // 6=exponent 7=sign 8=any2 9=done
    if (current_ == '-') {
      Add(current_);
      state = 1;
    } else if (current_ == '0') {
      Add(current_);
      state = 2;
    } else {
      Add(current_);
      state = 3;
    }
    while (state != 9) {
      switch (state) {
        case 1:
          number_type = Token::value_integer;
          Get();
          if (current_ == '0') {
            Add(current_);
            state = 2;
          } else if (current_ >= '1' && current_ <= '9') {
            Add(current_);
            state = 3;
          } else {
            error_message_ = "invalid number; expected digit after '-'";
            return Token::parse_error;
          }
          break;
        case 2:
          Get();
          if (current_ == '.') {
            Add('.');
            state = 4;
          } else if (current_ == 'e' || current_ == 'E') {
            Add(current_);
            state = 6;
          } else {
            state = 9;
          }
          break;
        case 3:
          Get();
          if (IsDigit(current_)) {
            Add(current_);
          } else if (current_ == '.') {
            Add('.');
            state = 4;
          } else if (current_ == 'e' || current_ == 'E') {
            Add(current_);
            state = 6;
          } else {
            state = 9;
          }
          break;
        case 4:
          number_type = Token::value_float;
          Get();
          if (IsDigit(current_)) {
            Add(current_);
            state = 5;
          } else {
            error_message_ = "invalid number; expected digit after '.'";
            return Token::parse_error;
          }
          break;
        case 5:
          Get();
          if (IsDigit(current_)) {
            Add(current_);
          } else if (current_ == 'e' || current_ == 'E') {
            Add(current_);
            state = 6;
          } else {
            state = 9;
          }
          break;
        case 6:
          number_type = Token::value_float;
          Get();
          if (current_ == '+' || current_ == '-') {
            Add(current_);
            state = 7;
          } else if (IsDigit(current_)) {
            Add(current_);
            state = 8;
          } else {
            error_message_ =
                "invalid number; expected '+', '-', or digit after exponent";
            return Token::parse_error;
          }
          break;
        case 7:
          Get();
          if (IsDigit(current_)) {
            Add(current_);
            state = 8;
          } else {
            error_message_ = "invalid number; expected digit after exponent sign";
            return Token::parse_error;
          }
          break;
        case 8:
          Get();
          if (IsDigit(current_)) {
            Add(current_);
          } else {
            state = 9;
          }
          break;
      }
    }
    Unget();

    char* endptr = nullptr;
    errno = 0;
    if (number_type == Token::value_unsigned) {
      const auto x = std::strtoull(token_buffer_.c_str(), &endptr, 10);
      if (errno == 0) {
        value_unsigned_ = x;
        return Token::value_unsigned;
      }
    } else if (number_type == Token::value_integer) {
      const auto x = std::strtoll(token_buffer_.c_str(), &endptr, 10);
      if (errno == 0) {
        value_integer_ = x;
        return Token::value_integer;
      }
    }
    value_float_ = std::strtod(token_buffer_.c_str(), &endptr);
    return Token::value_float;
  }

  Token Scan() {
    if (chars_read_total_ == 0 && !SkipBom()) {
      error_message_ = "invalid BOM; must be 0xEF 0xBB 0xBF if given";
      return Token::parse_error;
    }
    SkipWhitespace();
    switch (current_) {
      case '[': return Token::begin_array;
      case ']': return Token::end_array;
      case '{': return Token::begin_object;
      case '}': return Token::end_object;
      case ':': return Token::name_separator;
      case ',': return Token::value_separator;
      case 't': return ScanLiteral("true", 4, Token::literal_true);
      case 'f': return ScanLiteral("false", 5, Token::literal_false);
      case 'n': return ScanLiteral("null", 4, Token::literal_null);
      case '"': return ScanString();
      case '-':
      case '0':
      case '1':
      case '2':
      case '3':
      case '4':
      case '5':
      case '6':
      case '7':
      case '8':
      case '9':
        return ScanNumber();
      case '\0':
      case kEOF:
        return Token::end_of_input;
      default:
        error_message_ = "invalid literal";
        return Token::parse_error;
    }
  }

  std::string PositionString() const {
    return " at line " + std::to_string(lines_read_ + 1) + ", column " +
           std::to_string(chars_read_current_line_);
  }

  size_t chars_read_total() const { return chars_read_total_; }
  const std::string& error_message() const { return error_message_; }
  const std::string& token_buffer() const { return token_buffer_; }
  uint64_t value_unsigned_ = 0;
  int64_t value_integer_ = 0;
  double value_float_ = 0;

 private:
  const std::string& input_;
  size_t pos_ = 0;
  int current_ = kEOF;
  bool next_unget_ = false;
  size_t chars_read_total_ = 0;
  size_t chars_read_current_line_ = 0;
  size_t lines_read_ = 0;
  std::string token_string_;
  std::string token_buffer_;
  std::string error_message_;
};

class Parser {
 public:
  explicit Parser(const std::string& input) : lexer_(input) {}

  bool Parse(Json& out, std::string& error) {
    GetToken();
    if (!ParseInternal(out, error)) {
      return false;
    }
    if (GetToken() != Token::end_of_input) {
      error = ParseError(ExceptionMessage(Token::end_of_input, "value"));
      return false;
    }
    return true;
  }

 private:
  Token GetToken() { return last_token_ = lexer_.Scan(); }

  std::string ParseError(const std::string& msg) {
    return "[json.exception.parse_error.101] parse error" +
           lexer_.PositionString() + ": " + msg;
  }

  std::string ExceptionMessage(Token expected, const std::string& context) {
    std::string error_msg = "syntax error ";
    if (!context.empty()) {
      error_msg += "while parsing " + context + " ";
    }
    error_msg += "- ";
    if (last_token_ == Token::parse_error) {
      error_msg += lexer_.error_message() + "; last read: '" +
                   lexer_.TokenString() + "'";
    } else {
      error_msg += std::string("unexpected ") + TokenName(last_token_);
    }
    if (expected != Token::uninitialized) {
      error_msg += std::string("; expected ") + TokenName(expected);
    }
    return error_msg;
  }

  // Store a scalar/container value in the current location.
  Json* Place(std::vector<Json*>& stack, Json& root, bool& root_set,
              Json&& value) {
    if (stack.empty()) {
      root = std::move(value);
      root_set = true;
      return &root;
    }
    Json* parent = stack.back();
    if (parent->is_array()) {
      parent->array_value.push_back(std::move(value));
      return &parent->array_value.back();
    }
    Json& slot = parent->object_value[pending_key_.back()];
    slot = std::move(value);
    return &slot;
  }

  bool ParseInternal(Json& root, std::string& error) {
    std::vector<bool> states;  // true = array, false = object
    std::vector<Json*> stack;
    bool root_set = false;
    bool skip_to_state_evaluation = false;

    while (true) {
      if (!skip_to_state_evaluation) {
        switch (last_token_) {
          case Token::begin_object: {
            Json* obj = Place(stack, root, root_set, Json::MakeObject());
            if (GetToken() == Token::end_object) {
              break;
            }
            if (last_token_ != Token::value_string) {
              error = ParseError(
                  ExceptionMessage(Token::value_string, "object key"));
              return false;
            }
            stack.push_back(obj);
            pending_key_.push_back(lexer_.token_buffer());
            if (GetToken() != Token::name_separator) {
              error = ParseError(
                  ExceptionMessage(Token::name_separator, "object separator"));
              return false;
            }
            states.push_back(false);
            GetToken();
            continue;
          }
          case Token::begin_array: {
            Json* arr = Place(stack, root, root_set, Json::MakeArray());
            if (GetToken() == Token::end_array) {
              break;
            }
            stack.push_back(arr);
            pending_key_.push_back(std::string());
            states.push_back(true);
            continue;
          }
          case Token::value_float: {
            const double res = lexer_.value_float_;
            if (!std::isfinite(res)) {
              error = "[json.exception.out_of_range.406] number overflow "
                      "parsing '" +
                      lexer_.TokenString() + "'";
              return false;
            }
            Json j;
            j.SetType(Json::Type::Float);
            j.float_value = res;
            Place(stack, root, root_set, std::move(j));
            break;
          }
          case Token::literal_false:
          case Token::literal_true: {
            Json j;
            j.SetType(Json::Type::Boolean);
            j.boolean_value = last_token_ == Token::literal_true;
            Place(stack, root, root_set, std::move(j));
            break;
          }
          case Token::literal_null: {
            Place(stack, root, root_set, Json());
            break;
          }
          case Token::value_integer: {
            Json j;
            j.SetType(Json::Type::Integer);
            j.integer_value = lexer_.value_integer_;
            Place(stack, root, root_set, std::move(j));
            break;
          }
          case Token::value_unsigned: {
            Json j;
            j.SetType(Json::Type::Unsigned);
            j.unsigned_value = lexer_.value_unsigned_;
            Place(stack, root, root_set, std::move(j));
            break;
          }
          case Token::value_string: {
            Json j;
            j.SetType(Json::Type::String);
            j.string_value = lexer_.token_buffer();
            Place(stack, root, root_set, std::move(j));
            break;
          }
          case Token::parse_error: {
            error = ParseError(ExceptionMessage(Token::uninitialized, "value"));
            return false;
          }
          case Token::end_of_input: {
            if (lexer_.chars_read_total() == 1) {
              error = ParseError(
                  "attempting to parse an empty input; check that your input "
                  "string or stream contains the expected JSON");
              return false;
            }
            error =
                ParseError(ExceptionMessage(Token::literal_or_value, "value"));
            return false;
          }
          default: {
            error =
                ParseError(ExceptionMessage(Token::literal_or_value, "value"));
            return false;
          }
        }
      } else {
        skip_to_state_evaluation = false;
      }

      if (states.empty()) {
        return true;
      }

      if (states.back()) {
        if (GetToken() == Token::value_separator) {
          GetToken();
          continue;
        }
        if (last_token_ == Token::end_array) {
          states.pop_back();
          stack.pop_back();
          pending_key_.pop_back();
          skip_to_state_evaluation = true;
          continue;
        }
        error = ParseError(ExceptionMessage(Token::end_array, "array"));
        return false;
      }

      if (GetToken() == Token::value_separator) {
        if (GetToken() != Token::value_string) {
          error =
              ParseError(ExceptionMessage(Token::value_string, "object key"));
          return false;
        }
        pending_key_.back() = lexer_.token_buffer();
        if (GetToken() != Token::name_separator) {
          error = ParseError(
              ExceptionMessage(Token::name_separator, "object separator"));
          return false;
        }
        GetToken();
        continue;
      }
      if (last_token_ == Token::end_object) {
        states.pop_back();
        stack.pop_back();
        pending_key_.pop_back();
        skip_to_state_evaluation = true;
        continue;
      }
      error = ParseError(ExceptionMessage(Token::end_object, "object"));
      return false;
    }
  }

  Lexer lexer_;
  Token last_token_ = Token::uninitialized;
  std::vector<std::string> pending_key_;
};

// Produce the shortest digit string that round trips. Returns digits and the
// decimal exponent such that value = digits * 10^exponent.
void ShortestDigits(double value, std::string& digits, int& exponent) {
  char buf[64];
  for (int precision = 1; precision <= 17; ++precision) {
    std::snprintf(buf, sizeof(buf), "%.*e", precision - 1, value);
    if (precision == 17 || std::strtod(buf, nullptr) == value) {
      break;
    }
  }
  // buf looks like d.dddde[+-]xx
  std::string s(buf);
  size_t e = s.find('e');
  std::string mantissa = s.substr(0, e);
  int exp10 = std::atoi(s.c_str() + e + 1);
  digits.clear();
  for (char c : mantissa) {
    if (c >= '0' && c <= '9') {
      digits.push_back(c);
    }
  }
  // Remove trailing zeros.
  while (digits.size() > 1 && digits.back() == '0') {
    digits.pop_back();
  }
  exponent = exp10 - static_cast<int>(digits.size()) + 1;
}

std::string AppendExponent(int e) {
  std::string out;
  if (e < 0) {
    e = -e;
    out += '-';
  } else {
    out += '+';
  }
  if (e < 10) {
    out += '0';
    out += static_cast<char>('0' + e);
  } else if (e < 100) {
    out += static_cast<char>('0' + e / 10);
    out += static_cast<char>('0' + e % 10);
  } else {
    out += static_cast<char>('0' + e / 100);
    e %= 100;
    out += static_cast<char>('0' + e / 10);
    out += static_cast<char>('0' + e % 10);
  }
  return out;
}

}  // namespace

std::string FormatDouble(double value) {
  if (!std::isfinite(value)) {
    return "null";
  }
  std::string out;
  if (std::signbit(value)) {
    out = "-";
    value = -value;
  }
  if (value == 0) {
    return out + "0.0";
  }
  std::string digits;
  int decimal_exponent = 0;
  ShortestDigits(value, digits, decimal_exponent);
  const int min_exp = -4;
  const int max_exp = 15;
  const int k = static_cast<int>(digits.size());
  const int n = k + decimal_exponent;

  if (k <= n && n <= max_exp) {
    out += digits + std::string(n - k, '0') + ".0";
    return out;
  }
  if (0 < n && n <= max_exp) {
    out += digits.substr(0, n) + "." + digits.substr(n);
    return out;
  }
  if (min_exp < n && n <= 0) {
    out += "0." + std::string(-n, '0') + digits;
    return out;
  }
  if (k == 1) {
    out += digits;
  } else {
    out += digits.substr(0, 1) + "." + digits.substr(1);
  }
  out += "e" + AppendExponent(n - 1);
  return out;
}

std::string Json::DumpNumber() const {
  switch (type_) {
    case Type::Integer: return std::to_string(integer_value);
    case Type::Unsigned: return std::to_string(unsigned_value);
    case Type::Float: return FormatDouble(float_value);
    default: return "";
  }
}

bool ParseJson(const std::string& input, Json& out, std::string& error) {
  Parser parser(input);
  return parser.Parse(out, error);
}

}  // namespace jt
