template <size_t N>
bool Bisearch(uint32_t ucs, const Interval (&table)[N]) {
  if (ucs < table[0].first || ucs > table[N - 1].last) {
    return false;
  }
  size_t min = 0;
  size_t max = N - 1;
  while (max >= min) {
    const size_t mid = (min + max) / 2;
    if (ucs > table[mid].last) {
      min = mid + 1;
    } else if (ucs < table[mid].first) {
      if (mid == 0) {
        return false;
      }
      max = mid - 1;
    } else {
      return true;
    }
  }
  return false;
}

}  // namespace

bool EatCodePoint(const std::string& input, size_t start, size_t* end,
                  uint32_t* ucs) {
  if (start >= input.size()) {
    *end = start + 1;
    return false;
  }
  const uint8_t c0 = static_cast<uint8_t>(input[start]);

  if ((c0 & 0b1000'0000) == 0b0000'0000) {
    *ucs = c0 & 0b1111'1111;
    *end = start + 1;
    if (*ucs == 0) {
      return false;
    }
    return true;
  }

  if ((c0 & 0b1110'0000) == 0b1100'0000 && start + 1 < input.size()) {
    const uint8_t c1 = static_cast<uint8_t>(input[start + 1]);
    *ucs = 0;
    *ucs += c0 & 0b0001'1111;
    *ucs <<= 6;
    *ucs += c1 & 0b0011'1111;
    *end = start + 2;
    return true;
  }

  if ((c0 & 0b1111'0000) == 0b1110'0000 && start + 2 < input.size()) {
    const uint8_t c1 = static_cast<uint8_t>(input[start + 1]);
    const uint8_t c2 = static_cast<uint8_t>(input[start + 2]);
    *ucs = 0;
    *ucs += c0 & 0b0000'1111;
    *ucs <<= 6;
    *ucs += c1 & 0b0011'1111;
    *ucs <<= 6;
    *ucs += c2 & 0b0011'1111;
    *end = start + 3;
    return true;
  }

  if ((c0 & 0b1111'1000) == 0b1111'0000 && start + 3 < input.size()) {
    const uint8_t c1 = static_cast<uint8_t>(input[start + 1]);
    const uint8_t c2 = static_cast<uint8_t>(input[start + 2]);
    const uint8_t c3 = static_cast<uint8_t>(input[start + 3]);
    *ucs = 0;
    *ucs += c0 & 0b0000'0111;
    *ucs <<= 6;
    *ucs += c1 & 0b0011'1111;
    *ucs <<= 6;
    *ucs += c2 & 0b0011'1111;
    *ucs <<= 6;
    *ucs += c3 & 0b0011'1111;
    *end = start + 4;
    return true;
  }

  *end = start + 1;
  return false;
}

bool IsControl(uint32_t ucs) {
  if (ucs == 0) {
    return true;
  }
  if (ucs < 32) {
    return ucs != 10;
  }
  if (ucs >= 0x7f && ucs < 0xa0) {
    return true;
  }
  return false;
}

bool IsCombining(uint32_t ucs) { return Bisearch(ucs, kCombining); }

bool IsFullWidth(uint32_t ucs) {
  if (ucs < 0x0300) {
    return false;
  }
  return Bisearch(ucs, kFullWidth);
}

int StringWidth(const std::string& input) {
  int width = 0;
  size_t start = 0;
  while (start < input.size()) {
    uint32_t codepoint = 0;
    if (!EatCodePoint(input, start, &start, &codepoint)) {
      continue;
    }
    if (IsControl(codepoint)) {
      continue;
    }
    if (IsCombining(codepoint)) {
      continue;
    }
    if (IsFullWidth(codepoint)) {
      width += 2;
      continue;
    }
    width += 1;
  }
  return width;
}

std::vector<std::string> Utf8ToGlyphs(const std::string& input) {
  std::vector<std::string> out;
  out.reserve(input.size());
  size_t start = 0;
  size_t end = 0;
  while (start < input.size()) {
    uint32_t codepoint = 0;
    const bool eaten = EatCodePoint(input, start, &end, &codepoint);
    if (!eaten || IsControl(codepoint)) {
      start = end;
      continue;
    }
    if (IsCombining(codepoint)) {
      if (!out.empty()) {
        out.back() += input.substr(start, end - start);
      }
      start = end;
      continue;
    }
    if (IsFullWidth(codepoint)) {
      out.push_back(input.substr(start, end - start));
      out.emplace_back("");
      start = end;
      continue;
    }
    out.push_back(input.substr(start, end - start));
    start = end;
  }
  return out;
}

}  // namespace jt
