void UpdatePixelStyle(std::stringstream& ss, const Pixel& prev,
                      const Pixel& next) {
  if ((next.bold != prev.bold) || (next.dim != prev.dim)) {
    ss << (((prev.bold && !next.bold) || (prev.dim && !next.dim)) ? "\x1B[22m"
                                                                   : "");
    ss << (next.bold ? "\x1B[1m" : "");
    ss << (next.dim ? "\x1B[2m" : "");
  }
  if (next.underlined != prev.underlined) {
    ss << (next.underlined ? "\x1B[4m" : "\x1B[24m");
  }
  if (next.inverted != prev.inverted) {
    ss << (next.inverted ? "\x1B[7m" : "\x1B[27m");
  }
  if (next.foreground_color != prev.foreground_color ||
      next.background_color != prev.background_color) {
    ss << "\x1B[" + next.foreground_color.Print(false) + "m";
    ss << "\x1B[" + next.background_color.Print(true) + "m";
  }
}
}  // namespace

std::string Screen::ToString() const {
  std::stringstream ss;
  const Pixel default_pixel;
  const Pixel* previous_pixel_ref = &default_pixel;

  for (int y = 0; y < dimy_; ++y) {
    if (y != 0) {
      UpdatePixelStyle(ss, *previous_pixel_ref, default_pixel);
      previous_pixel_ref = &default_pixel;
      ss << "\r\n";
    }
    bool previous_fullwidth = false;
    for (const auto& pixel : pixels_[y]) {
      if (!previous_fullwidth) {
        UpdatePixelStyle(ss, *previous_pixel_ref, pixel);
        previous_pixel_ref = &pixel;
        if (pixel.character.empty()) {
          ss << " ";
        } else {
          ss << pixel.character;
        }
      }
      previous_fullwidth = (StringWidth(pixel.character) == 2);
    }
  }
  UpdatePixelStyle(ss, *previous_pixel_ref, default_pixel);
  return ss.str();
}

