namespace {
Selection Saturate(int start_x, int start_y, int end_x, int end_y, Box box) {
  const bool start_outside = !box.Contain(start_x, start_y);
  const bool end_outside = !box.Contain(end_x, end_y);
  const bool properly_ordered =
      start_y < end_y || (start_y == end_y && start_x <= end_x);
  if (properly_ordered) {
    if (start_outside) {
      start_x = box.x_min;
      start_y = box.y_min;
    }
    if (end_outside) {
      end_x = box.x_max;
      end_y = box.y_max;
    }
  } else {
    if (start_outside) {
      start_x = box.x_max;
      start_y = box.y_max;
    }
    if (end_outside) {
      end_x = box.x_min;
      end_y = box.y_min;
    }
  }
  return Selection(start_x, start_y, end_x, end_y);
}
}  // namespace

Selection Selection::SaturateHorizontal(Box box) const {
  return Saturate(start_x_, start_y_, end_x_, end_y_, box);
}

Selection Selection::SaturateVertical(Box box) const {
  return Saturate(start_x_, start_y_, end_x_, end_y_, box);
}

