void Node::ComputeRequirement() {
  for (auto& child : children_) {
    child->ComputeRequirement();
  }
}

void Node::SetBox(Box box) { box_ = box; }

void Node::Select(Selection& selection) {
  if (Box::Intersection(selection.GetBox(), box_).IsEmpty()) {
    return;
  }
  for (auto& child : children_) {
    child->Select(selection);
  }
}

void Node::Render(Screen& screen) {
  for (auto& child : children_) {
    child->Render(screen);
  }
}

void Node::Check(Status* status) {
  for (auto& child : children_) {
    child->Check(status);
  }
  status->need_iteration |= (status->iteration == 0);
}

void Render(Screen& screen, Node* node, Selection& selection) {
  Box box;
  box.x_min = 0;
  box.y_min = 0;
  box.x_max = screen.dimx() - 1;
  box.y_max = screen.dimy() - 1;

  Node::Status status;
  node->Check(&status);
  const int max_iterations = 20;
  while (status.need_iteration && status.iteration < max_iterations) {
    node->ComputeRequirement();
    node->SetBox(box);
    status.need_iteration = false;
    status.iteration++;
    node->Check(&status);
  }

  if (!selection.IsEmpty()) {
    node->Select(selection);
  }

  if (node->requirement().focused.enabled) {
    const Box& b = node->requirement().focused.node->box();
    screen.cursor.x = b.x_max;
    screen.cursor.y = b.y_max;
    screen.cursor.hidden = true;
  } else {
    screen.cursor.x = screen.dimx() - 1;
    screen.cursor.y = screen.dimy() - 1;
    screen.cursor.hidden = true;
  }

  screen.stencil = box;
  node->Render(screen);
  screen.ApplyShader();
}

void Render(Screen& screen, const Element& node) {
  Selection selection;
  Render(screen, node.get(), selection);
}

