// Flexbox specialized for paragraphs: row direction, wrapping, gap_x = 1.
class Paragraph : public Node {
 public:
  explicit Paragraph(Elements children) : Node(std::move(children)) {}

  struct Block {
    int min_x = 0;
    int min_y = 0;
    int x = 0;
    int y = 0;
    int dim_x = 0;
    int dim_y = 0;
  };
  struct Line {
    std::vector<size_t> blocks;
    int x = 0;
    int y = 0;
    int dim_x = 0;
    int dim_y = 0;
  };

  void Layout(int size_x, int size_y) {
    blocks_.assign(children_.size(), Block());
    for (size_t i = 0; i < children_.size(); ++i) {
      blocks_[i].min_x = children_[i]->requirement().min_x;
      blocks_[i].min_y = children_[i]->requirement().min_y;
    }
    lines_.clear();
    Line line;
    int x = 0;
    for (size_t i = 0; i < blocks_.size(); ++i) {
      if (x + blocks_[i].min_x > size_x) {
        x = 0;
        if (!line.blocks.empty()) {
          lines_.push_back(line);
        }
        line = Line();
      }
      line.blocks.push_back(i);
      x += blocks_[i].min_x + 1;
    }
    if (!line.blocks.empty()) {
      lines_.push_back(line);
    }

    // X axis.
    for (auto& l : lines_) {
      std::vector<box_helper::Element> elements;
      for (size_t i : l.blocks) {
        box_helper::Element e;
        e.min_size = blocks_[i].min_x;
        elements.push_back(e);
      }
      box_helper::Compute(&elements,
                          size_x - (static_cast<int>(l.blocks.size()) - 1));
      int bx = 0;
      for (size_t k = 0; k < l.blocks.size(); ++k) {
        blocks_[l.blocks[k]].x = bx;
        blocks_[l.blocks[k]].dim_x = elements[k].size;
        bx += elements[k].size + 1;
      }
    }

    // Y axis.
    std::vector<box_helper::Element> ys(lines_.size());
    for (size_t i = 0; i < lines_.size(); ++i) {
      ys[i].min_size = 0;
      for (size_t b : lines_[i].blocks) {
        ys[i].min_size = std::max(ys[i].min_size, blocks_[b].min_y);
      }
    }
    box_helper::Compute(&ys, size_y);
    int y = 0;
    for (size_t i = 0; i < lines_.size(); ++i) {
      for (size_t b : lines_[i].blocks) {
        blocks_[b].y = y;
        blocks_[b].dim_y = std::min(blocks_[b].min_y, ys[i].size);
      }
      lines_[i].y = y;
      lines_[i].dim_y = ys[i].size;
      int x_min = INT_MAX;
      int x_max = INT_MIN;
      for (size_t b : lines_[i].blocks) {
        x_min = std::min(x_min, blocks_[b].x);
        x_max = std::max(x_max, blocks_[b].x + blocks_[b].dim_x);
      }
      lines_[i].x = x_min;
      lines_[i].dim_x = x_max - x_min;
      y += ys[i].size;
    }
  }

  void ComputeRequirement() override {
    for (auto& child : children_) {
      child->ComputeRequirement();
    }
    Layout(asked_, 100000);
    requirement_ = Requirement();
    if (blocks_.empty()) {
      return;
    }
    Box box;
    box.x_min = blocks_[0].x;
    box.y_min = blocks_[0].y;
    box.x_max = blocks_[0].x + blocks_[0].dim_x;
    box.y_max = blocks_[0].y + blocks_[0].dim_y;
    for (auto& b : blocks_) {
      box.x_min = std::min(box.x_min, b.x);
      box.y_min = std::min(box.y_min, b.y);
      box.x_max = std::max(box.x_max, b.x + b.dim_x);
      box.y_max = std::max(box.y_max, b.y + b.dim_y);
    }
    requirement_.min_x = box.x_max - box.x_min;
    requirement_.min_y = box.y_max - box.y_min;
  }

  void SetBox(Box box) override {
    Node::SetBox(box);
    const int asked_previous = asked_;
    asked_ = std::min(asked_, box.x_max - box.x_min + 1);
    need_iteration_ = (asked_ != asked_previous);

    Layout(box.x_max - box.x_min + 1, box.y_max - box.y_min + 1);
    for (size_t i = 0; i < children_.size(); ++i) {
      auto& b = blocks_[i];
      Box children_box;
      children_box.x_min = box.x_min + b.x;
      children_box.y_min = box.y_min + b.y;
      children_box.x_max = box.x_min + b.x + b.dim_x - 1;
      children_box.y_max = box.y_min + b.y + b.dim_y - 1;
      const Box intersection = Box::Intersection(children_box, box);
      children_[i]->SetBox(intersection);
      need_iteration_ |= (intersection != children_box);
    }
  }

  void Select(Selection& selection) override {
    if (Box::Intersection(selection.GetBox(), box_).IsEmpty()) {
      return;
    }
    Selection selection_lines = selection.SaturateHorizontal(box_);
    for (auto& line : lines_) {
      Box box;
      box.x_min = box_.x_min + line.x;
      box.x_max = box_.x_min + line.x + line.dim_x - 1;
      box.y_min = box_.y_min + line.y;
      box.y_max = box_.y_min + line.y + line.dim_y - 1;
      if (Box::Intersection(selection.GetBox(), box).IsEmpty()) {
        continue;
      }
      Selection selection_line = selection_lines.SaturateVertical(box);
      for (size_t b : line.blocks) {
        children_[b]->Select(selection_line);
      }
    }
  }

  void Check(Status* status) override {
    for (auto& child : children_) {
      child->Check(status);
    }
    if (status->iteration == 0) {
      asked_ = 6000;
      need_iteration_ = true;
    }
    status->need_iteration |= need_iteration_;
  }

 private:
  int asked_ = std::numeric_limits<int>::max();
  bool need_iteration_ = true;
  std::vector<Block> blocks_;
  std::vector<Line> lines_;
};

class GridBox : public Node {
 public:
  explicit GridBox(std::vector<Elements> lines) : lines_(std::move(lines)) {
    y_size_ = static_cast<int>(lines_.size());
    for (const auto& line : lines_) {
      x_size_ = std::max(x_size_, static_cast<int>(line.size()));
    }
    for (auto& line : lines_) {
      while (line.size() < static_cast<size_t>(x_size_)) {
        line.push_back(filler());
      }
    }
    for (auto& line : lines_) {
      for (auto& cell : line) {
        children_.push_back(cell);
      }
    }
  }

  void ComputeRequirement() override {
    requirement_ = Requirement();
    for (auto& line : lines_) {
      for (auto& cell : line) {
        cell->ComputeRequirement();
      }
    }
    std::vector<int> size_x(x_size_, 0);
    std::vector<int> size_y(y_size_, 0);
    for (int x = 0; x < x_size_; ++x) {
      for (int y = 0; y < y_size_; ++y) {
        size_x[x] = std::max(size_x[x], lines_[y][x]->requirement().min_x);
        size_y[y] = std::max(size_y[y], lines_[y][x]->requirement().min_y);
      }
    }
    for (int v : size_x) {
      requirement_.min_x += v;
    }
    for (int v : size_y) {
      requirement_.min_y += v;
    }

    // Forward the focused requirement.
    int offset_y = 0;
    for (int y = 0; y < y_size_; ++y) {
      int offset_x = 0;
      for (int x = 0; x < x_size_; ++x) {
        const auto& f = lines_[y][x]->requirement().focused;
        if (requirement_.focused.Prefer(f)) {
          requirement_.focused = f;
          requirement_.focused.box.Shift(offset_x, offset_y);
        }
        offset_x += size_x[x];
      }
      offset_y += size_y[y];
    }
  }

  void SetBox(Box box) override {
    Node::SetBox(box);
    box_helper::Element init;
    init.min_size = 0;
    init.flex_grow = 1024;
    init.flex_shrink = 1024;
    std::vector<box_helper::Element> elements_x(x_size_, init);
    std::vector<box_helper::Element> elements_y(y_size_, init);
    for (int y = 0; y < y_size_; ++y) {
      for (int x = 0; x < x_size_; ++x) {
        const auto& r = lines_[y][x]->requirement();
        auto& e_x = elements_x[x];
        auto& e_y = elements_y[y];
        e_x.min_size = std::max(e_x.min_size, r.min_x);
        e_y.min_size = std::max(e_y.min_size, r.min_y);
        e_x.flex_grow = std::min(e_x.flex_grow, r.flex_grow_x);
        e_y.flex_grow = std::min(e_y.flex_grow, r.flex_grow_y);
        e_x.flex_shrink = std::min(e_x.flex_shrink, r.flex_shrink_x);
        e_y.flex_shrink = std::min(e_y.flex_shrink, r.flex_shrink_y);
      }
    }
    const int target_size_x = box.x_max - box.x_min + 1;
    const int target_size_y = box.y_max - box.y_min + 1;
    box_helper::Compute(&elements_x, target_size_x);
    if (greedy_y_) {
      ComputeGreedy(&elements_y, target_size_y);
    } else {
      box_helper::Compute(&elements_y, target_size_y);
    }

    Box box_y = box;
    int y = box_y.y_min;
    for (int iy = 0; iy < y_size_; ++iy) {
      box_y.y_min = y;
      y += elements_y[iy].size;
      box_y.y_max = y - 1;
      Box box_x = box_y;
      int x = box_x.x_min;
      for (int ix = 0; ix < x_size_; ++ix) {
        box_x.x_min = x;
        x += elements_x[ix].size;
        box_x.x_max = x - 1;
        lines_[iy][ix]->SetBox(box_x);
      }
    }
  }

  static void ComputeGreedy(std::vector<box_helper::Element>* elements,
                            int target_size) {
    int size = 0;
    int fixed = 0;
    for (auto& e : *elements) {
      size += e.min_size;
      if (e.flex_shrink == 0) {
        fixed += e.min_size;
      }
    }
    if (size <= target_size || fixed > target_size) {
      box_helper::Compute(elements, target_size);
      return;
    }
    int remaining = target_size - fixed;
    for (auto& e : *elements) {
      if (e.flex_shrink == 0) {
        e.size = e.min_size;
        continue;
      }
      e.size = std::min(e.min_size, remaining);
      remaining -= e.size;
    }
  }

  void Render(Screen& screen) override {
    for (auto& line : lines_) {
      for (auto& cell : line) {
        cell->Render(screen);
      }
    }
  }

  void Select(Selection& selection) override {
    if (Box::Intersection(selection.GetBox(), box_).IsEmpty()) {
      return;
    }
    for (auto& line : lines_) {
      for (auto& cell : line) {
        cell->Select(selection);
      }
    }
  }

  bool greedy_y_ = false;

 private:
  int x_size_ = 0;
  int y_size_ = 0;
  std::vector<Elements> lines_;
};

class SeparatorCharacter : public Node {
 public:
  explicit SeparatorCharacter(std::string value) : value_(std::move(value)) {}
  void ComputeRequirement() override {
    requirement_ = Requirement();
    requirement_.min_x = 1;
    requirement_.min_y = 1;
  }
  void Render(Screen& screen) override {
    for (int y = box_.y_min; y <= box_.y_max; ++y) {
      for (int x = box_.x_min; x <= box_.x_max; ++x) {
        Pixel& pixel = screen.PixelAt(x, y);
        pixel.character = value_;
        pixel.automerge = true;
      }
    }
  }

 private:
  std::string value_;
};

class SeparatorAuto : public Node {
 public:
  explicit SeparatorAuto(int style) : style_(style) {}
  void ComputeRequirement() override {
    requirement_ = Requirement();
    requirement_.min_x = 1;
    requirement_.min_y = 1;
  }
  void Render(Screen& screen) override {
    static const char* charset[][2] = {
        {"│", "─"}, {"┃", "━"}, {"║", "═"}, {"│", "─"}, {" ", " "}};
    const bool is_column = (box_.x_max == box_.x_min);
    const bool is_line = (box_.y_min == box_.y_max);
    const std::string c = charset[style_][int(is_line && !is_column)];
    for (int y = box_.y_min; y <= box_.y_max; ++y) {
      for (int x = box_.x_min; x <= box_.x_max; ++x) {
        Pixel& pixel = screen.PixelAt(x, y);
        pixel.character = c;
        pixel.automerge = true;
      }
    }
  }

 private:
  int style_;
};

