const char* kTableCharset[5][6] = {
    {"┌", "┐", "└", "┘", "─", "│"},
    {"┏", "┓", "┗", "┛", "━", "┃"},
    {"╔", "╗", "╚", "╝", "═", "║"},
    {"╭", "╮", "╰", "╯", "─", "│"},
    {" ", " ", " ", " ", " ", " "},
};

int Wrap(int input, int modulo) {
  if (modulo == 0) {
    return 0;
  }
  input %= modulo;
  input += modulo;
  input %= modulo;
  return input;
}
}  // namespace

Table::Table(std::vector<Elements> input) {
  input_dim_y_ = static_cast<int>(input.size());
  input_dim_x_ = 0;
  for (auto& line : input) {
    input_dim_x_ = std::max(input_dim_x_, static_cast<int>(line.size()));
  }
  dim_y_ = 2 * input_dim_y_ + 1;
  dim_x_ = 2 * input_dim_x_ + 1;
  elements_.resize(dim_y_);
  for (auto& line : elements_) {
    line.resize(dim_x_);
  }
  int y = 1;
  for (auto& line : input) {
    int x = 1;
    for (auto& cell : line) {
      elements_[y][x] = std::move(cell);
      x += 2;
    }
    y += 2;
  }
  for (int yy = 0; yy < dim_y_; ++yy) {
    for (int xx = 0; xx < dim_x_; ++xx) {
      auto& element = elements_[yy][xx];
      if (yy % 2 == 0 || xx % 2 == 0) {
        element = emptyElement();
        continue;
      }
      if (!element) {
        element = emptyElement();
      }
    }
  }
}

TableSelection Table::SelectAll() {
  TableSelection output;
  output.table_ = this;
  output.x_min_ = 0;
  output.x_max_ = dim_x_ - 1;
  output.y_min_ = 0;
  output.y_max_ = dim_y_ - 1;
  return output;
}

TableSelection Table::SelectRectangle(int column_min, int column_max,
                                      int row_min, int row_max) {
  column_min = Wrap(column_min, input_dim_x_);
  column_max = Wrap(column_max, input_dim_x_);
  if (column_min > column_max) {
    std::swap(column_min, column_max);
  }
  row_min = Wrap(row_min, input_dim_y_);
  row_max = Wrap(row_max, input_dim_y_);
  if (row_min > row_max) {
    std::swap(row_min, row_max);
  }
  TableSelection output;
  output.table_ = this;
  output.x_min_ = 2 * column_min;
  output.x_max_ = 2 * column_max + 2;
  output.y_min_ = 2 * row_min;
  output.y_max_ = 2 * row_max + 2;
  return output;
}

TableSelection Table::SelectCell(int column, int row) {
  return SelectRectangle(column, column, row, row);
}
TableSelection Table::SelectRow(int index) {
  return SelectRectangle(0, -1, index, index);
