const std::map<TileEncoding, std::string>& TileMapInverse() {
  static const std::map<TileEncoding, std::string> m = [] {
    std::map<TileEncoding, std::string> out;
    for (const auto& it : TileMap()) {
      if (it.first == "╍" || it.first == "╏") {
        continue;
      }
      out.emplace(it.second, it.first);
    }
    return out;
  }();
  return m;
}

void UpgradeLeftRight(std::string& left, std::string& right) {
  const auto& map = TileMap();
  const auto& inv = TileMapInverse();
  const auto it_left = map.find(left);
  if (it_left == map.end()) {
    return;
  }
  const auto it_right = map.find(right);
  if (it_right == map.end()) {
    return;
  }
  const TileEncoding l = it_left->second;
  const TileEncoding r = it_right->second;
  if (l.right == 0 && r.left != 0) {
    TileEncoding e = l;
    e.right = r.left;
    const auto up = inv.find(e);
    if (up != inv.end()) {
      left = up->second;
    }
  }
  if (r.left == 0 && l.right != 0) {
    TileEncoding e = r;
    e.left = l.right;
    const auto up = inv.find(e);
    if (up != inv.end()) {
      right = up->second;
    }
  }
}

void UpgradeTopDown(std::string& top, std::string& down) {
  const auto& map = TileMap();
  const auto& inv = TileMapInverse();
  const auto it_top = map.find(top);
  if (it_top == map.end()) {
    return;
  }
  const auto it_down = map.find(down);
  if (it_down == map.end()) {
    return;
  }
  const TileEncoding t = it_top->second;
  const TileEncoding d = it_down->second;
  if (t.down == 0 && d.top != 0) {
    TileEncoding e = t;
    e.down = d.top;
    const auto up = inv.find(e);
    if (up != inv.end()) {
      top = up->second;
    }
  }
  if (d.top == 0 && t.down != 0) {
    TileEncoding e = d;
    e.top = t.down;
    const auto up = inv.find(e);
    if (up != inv.end()) {
      down = up->second;
    }
  }
}
