namespace {
Selection Saturate(int start_x, int start_y, int end_x, int end_y, Box box) {
  const bool start_outside = !box.Contain(start_x, start_y);
  const bool end_outside = !box.Contain(end_x, end_y);
  const bool properly_ordered =
      start_y < end_y || (start_y == end_y && start_x <= end_x);
  if (properly_ordered) {
    if (start_outside) {
      start_x = box.x_min;
      start_y = box.y_min;
    }
    if (end_outside) {
      end_x = box.x_max;
      end_y = box.y_max;
    }
  } else {
    if (start_outside) {
      start_x = box.x_max;
      start_y = box.y_max;
    }
    if (end_outside) {
      end_x = box.x_min;
      end_y = box.y_min;
    }
  }
  return Selection(start_x, start_y, end_x, end_y);
}
}  // namespace

Selection Selection::SaturateHorizontal(Box box) const {
  return Saturate(start_x_, start_y_, end_x_, end_y_, box);
}

Selection Selection::SaturateVertical(Box box) const {
  return Saturate(start_x_, start_y_, end_x_, end_y_, box);
}

// ---------------------------------------------------------------------------
// Node
void Node::ComputeRequirement() {
  for (auto& child : children_) {
    child->ComputeRequirement();
  }
}

void Node::SetBox(Box box) { box_ = box; }

void Node::Select(Selection& selection) {
  if (Box::Intersection(selection.GetBox(), box_).IsEmpty()) {
    return;
  }
  for (auto& child : children_) {
    child->Select(selection);
  }
}

void Node::Render(Screen& screen) {
  for (auto& child : children_) {
    child->Render(screen);
  }
}

void Node::Check(Status* status) {
  for (auto& child : children_) {
    child->Check(status);
  }
  status->need_iteration |= (status->iteration == 0);
}

void Render(Screen& screen, Node* node, Selection& selection) {
  Box box;
  box.x_min = 0;
  box.y_min = 0;
  box.x_max = screen.dimx() - 1;
  box.y_max = screen.dimy() - 1;

  Node::Status status;
  node->Check(&status);
  const int max_iterations = 20;
  while (status.need_iteration && status.iteration < max_iterations) {
    node->ComputeRequirement();
    node->SetBox(box);
    status.need_iteration = false;
    status.iteration++;
    node->Check(&status);
  }

  if (!selection.IsEmpty()) {
    node->Select(selection);
  }

  if (node->requirement().focused.enabled) {
    const Box& b = node->requirement().focused.node->box();
    screen.cursor.x = b.x_max;
    screen.cursor.y = b.y_max;
    screen.cursor.hidden = true;
  } else {
    screen.cursor.x = screen.dimx() - 1;
    screen.cursor.y = screen.dimy() - 1;
    screen.cursor.hidden = true;
  }

  screen.stencil = box;
  node->Render(screen);
  screen.ApplyShader();
}

void Render(Screen& screen, const Element& node) {
  Selection selection;
  Render(screen, node.get(), selection);
}

