class Text : public Node {
 public:
  explicit Text(std::string text) : text_(std::move(text)) {}

  void ComputeRequirement() override {
    requirement_ = Requirement();
    requirement_.min_x = StringWidth(text_);
    requirement_.min_y = 1;
  }

  void Select(Selection& selection) override {
    if (Box::Intersection(selection.GetBox(), box_).IsEmpty()) {
      return;
    }
    const Selection saturated = selection.SaturateHorizontal(box_);
    has_selection_ = true;
    selection_start_ = saturated.GetBox().x_min;
    selection_end_ = saturated.GetBox().x_max;
  }

  void Render(Screen& screen) override {
    int x = box_.x_min;
    const int y = box_.y_min;
    if (y > box_.y_max) {
      return;
    }
    for (const auto& cell : Utf8ToGlyphs(text_)) {
      if (x > box_.x_max) {
        break;
      }
      if (cell == "\n") {
        continue;
      }
      Pixel& pixel = screen.PixelAt(x, y);
      pixel.character = cell;
      if (has_selection_ && x >= selection_start_ && x <= selection_end_) {
        pixel.inverted = !pixel.inverted;
      }
      ++x;
    }
  }

 private:
  std::string text_;
  bool has_selection_ = false;
  int selection_start_ = 0;
  int selection_end_ = 0;
};

class VBox : public Node {
 public:
  explicit VBox(Elements children) : Node(std::move(children)) {}

  void ComputeRequirement() override {
    requirement_ = Requirement();
    for (auto& child : children_) {
      child->ComputeRequirement();
      if (requirement_.focused.Prefer(child->requirement().focused)) {
        requirement_.focused = child->requirement().focused;
        requirement_.focused.box.Shift(0, requirement_.min_y);
      }
      requirement_.min_y += child->requirement().min_y;
      requirement_.min_x =
          std::max(requirement_.min_x, child->requirement().min_x);
    }
  }

  void SetBox(Box box) override {
    Node::SetBox(box);
    std::vector<box_helper::Element> elements(children_.size());
    for (size_t i = 0; i < children_.size(); ++i) {
      auto& element = elements[i];
      const auto& r = children_[i]->requirement();
      element.min_size = r.min_y;
      element.flex_grow = r.flex_grow_y;
      element.flex_shrink = r.flex_shrink_y;
    }
    const int target_size = box.y_max - box.y_min + 1;
    box_helper::Compute(&elements, target_size);
    int y = box.y_min;
    for (size_t i = 0; i < children_.size(); ++i) {
      box.y_min = y;
      box.y_max = y + elements[i].size - 1;
      children_[i]->SetBox(box);
      y = box.y_max + 1;
    }
  }

  void Select(Selection& selection) override {
    if (Box::Intersection(selection.GetBox(), box_).IsEmpty()) {
      return;
    }
    Selection saturated = selection.SaturateVertical(box_);
    for (auto& child : children_) {
      child->Select(saturated);
    }
  }
};

