Element paragraph(const std::string& the_text) {
  Elements lines;
  for (const auto& line : SplitString(the_text, '\n')) {
    Elements words;
    for (const auto& word : SplitString(line, ' ')) {
      words.push_back(text(word));
    }
    lines.push_back(std::make_shared<Paragraph>(std::move(words)));
  }
  return vbox(std::move(lines));
}

