namespace {

class ContainerBase : public ComponentBase {
 public:
  explicit ContainerBase(Components children) {
    for (Component& child : children) {
      Add(std::move(child));
    }
  }

  bool OnEvent(Event event) override {
    if (event.is_mouse()) {
      return OnMouseEvent(event);
    }
    if (!Focused()) {
      return false;
    }
    if (ActiveChild() && ActiveChild()->OnEvent(event)) {
      return true;
    }
    return EventHandler(event);
  }

  Component ActiveChild() override {
    if (children_.empty()) {
      return nullptr;
    }
    return children_[static_cast<size_t>(selector_) % children_.size()];
  }

  void SetActiveChild(ComponentBase* child) override {
    for (size_t i = 0; i < children_.size(); ++i) {
      if (children_[i].get() == child) {
        selector_ = static_cast<int>(i);
        return;
      }
    }
  }

 protected:
  virtual bool EventHandler(Event /*unused*/) { return false; }
  virtual bool OnMouseEvent(Event event) {
    return ComponentBase::OnEvent(std::move(event));
  }

  void MoveSelector(int dir) {
    for (int i = selector_ + dir; i >= 0 && i < int(children_.size());
         i += dir) {
      if (children_[i]->Focusable()) {
        selector_ = i;
        return;
      }
    }
  }

  void MoveSelectorWrap(int dir) {
    if (children_.empty()) {
      return;
    }
    for (size_t offset = 1; offset < children_.size(); ++offset) {
      const size_t i =
          (size_t(selector_ + int(offset) * dir + int(children_.size())) %
           children_.size());
      if (children_[i]->Focusable()) {
        selector_ = int(i);
        return;
      }
    }
  }

  int selector_ = 0;
  Box box_;
};

class VerticalContainer : public ContainerBase {
 public:
  using ContainerBase::ContainerBase;

  Element OnRender() override {
    Elements elements;
    for (auto& it : children_) {
      elements.push_back(it->Render());
    }
    if (elements.empty()) {
      return text("Empty container") | reflect(box_);
    }
    return vbox(std::move(elements)) | reflect(box_);
  }

  bool EventHandler(Event event) override {
    const int old_selected = selector_;
    if (event == Event::ArrowUp || event == Event::Character("k")) {
      MoveSelector(-1);
    }
    if (event == Event::ArrowDown || event == Event::Character("j")) {
      MoveSelector(+1);
    }
    if (event == Event::PageUp) {
      for (int i = 0; i < box_.y_max - box_.y_min; ++i) {
        MoveSelector(-1);
      }
    }
    if (event == Event::PageDown) {
      for (int i = 0; i < box_.y_max - box_.y_min; ++i) {
