Component Renderer(std::function<Element(bool)> render) {
  class Impl : public ComponentBase {
   public:
    explicit Impl(std::function<Element(bool)> render)
        : render_(std::move(render)) {}

   private:
    Element OnRender() override { return render_(Focused()) | reflect(box_); }
    bool Focusable() const override { return true; }
    bool OnEvent(Event event) override {
      if (event.is_mouse() && box_.Contain(event.mouse().x, event.mouse().y)) {
        if (!CaptureMouse(event)) {
          return false;
        }
        TakeFocus();
      }
      return false;
    }
    std::function<Element(bool)> render_;
    Box box_;
  };
  return Make<Impl>(std::move(render));
}

Component CatchEvent(Component child, std::function<bool(Event)> on_event) {
  class Impl : public ComponentBase {
   public:
    explicit Impl(std::function<bool(Event)> on_event)
        : on_event_(std::move(on_event)) {}
