const Event Event::TabReverse = Event::Special("\x1B[Z");
const Event Event::PageUp = Event::Special("\x1B[5~");
const Event Event::PageDown = Event::Special("\x1B[6~");
const Event Event::Home = Event::Special("\x1B[H");
const Event Event::End = Event::Special("\x1B[F");
const Event Event::CtrlC = Event::Special("\x03");

// ---------------------------------------------------------------------------
// ComponentBase
ComponentBase::~ComponentBase() { DetachAllChildren(); }

void ComponentBase::Add(Component child) {
  child->Detach();
  child->parent_ = this;
  children_.push_back(std::move(child));
}

void ComponentBase::Detach() {
  if (parent_ == nullptr) {
    return;
  }
  auto it = std::find_if(parent_->children_.begin(), parent_->children_.end(),
                         [this](const Component& that) {
                           return this == that.get();
                         });
  ComponentBase* parent = parent_;
  parent_ = nullptr;
  parent->children_.erase(it);
}

void ComponentBase::DetachAllChildren() {
  while (!children_.empty()) {
    children_[0]->Detach();
  }
}

