#include "terminal.hpp"

#include <fcntl.h>
#include <poll.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <termios.h>
#include <unistd.h>

#include <cerrno>
#include <chrono>
#include <cstring>
#include <map>
#include <vector>

namespace jt {

namespace {

volatile sig_atomic_t g_signal_winch = 0;
volatile sig_atomic_t g_signal_exit = 0;
int g_signal_pipe[2] = {-1, -1};

void OnSignal(int signal) {
  if (signal == SIGWINCH) {
    g_signal_winch = 1;
  } else {
    g_signal_exit = signal;
  }
  if (g_signal_pipe[1] >= 0) {
    char c = 0;
    ssize_t r = write(g_signal_pipe[1], &c, 1);
    (void)r;
  }
}

struct Dimensions {
  int dimx;
  int dimy;
};

Dimensions TerminalSize() {
  winsize w{};
  const int status = ioctl(STDOUT_FILENO, TIOCGWINSZ, &w);
  if (status < 0 || w.ws_col == 0 || w.ws_row == 0) {
    return Dimensions{80, 24};
  }
  return Dimensions{w.ws_col, w.ws_row};
}

// ---------------------------------------------------------------------------
// Terminal input parser.
class InputParser {
 public:
  explicit InputParser(std::function<void(Event)> out) : out_(std::move(out)) {}

  void Add(char c) {
    pending_ += c;
    timeout_ = 0;
    position_ = -1;
    Send(Parse());
  }

  void Timeout(int ms) {
    timeout_ += ms;
    if (timeout_ < 50) {
      return;
    }
    timeout_ = 0;
    if (!pending_.empty()) {
      Send(SPECIAL);
    }
  }

  bool HasPending() const { return !pending_.empty(); }

 private:
  enum Type { UNCOMPLETED, DROP, CHARACTER, SPECIAL, MOUSE, CURSOR_POSITION };
  struct Output {
    Type type;
    Mouse mouse;
    int cursor_x = 0;
    int cursor_y = 0;
    Output(Type t) : type(t) {}  // NOLINT
  };

  bool Eat() {
    position_++;
    return position_ < static_cast<int>(pending_.size());
  }
  unsigned char Current() const {
    return static_cast<unsigned char>(pending_[position_]);
  }

  void Send(Output output) {
    static const std::map<std::string, std::string> uniformize = {
        {"\r", "\n"},
        {std::string({8}), std::string({127})},
        {"\x1BOA", "\x1B[A"},
        {"\x1BOB", "\x1B[B"},
        {"\x1BOC", "\x1B[C"},
        {"\x1BOD", "\x1B[D"},
        {"\x1BOH", "\x1B[H"},
        {"\x1BOF", "\x1B[F"},
    };
    switch (output.type) {
      case UNCOMPLETED:
        return;
      case DROP:
        pending_.clear();
        return;
      case CHARACTER:
        out_(Event::Character(pending_));
        pending_.clear();
        return;
      case SPECIAL: {
        auto it = uniformize.find(pending_);
        if (it != uniformize.end()) {
          pending_ = it->second;
        }
        out_(Event::Special(pending_));
        pending_.clear();
        return;
      }
      case MOUSE:
        out_(Event::MouseEvent(pending_, output.mouse));
        pending_.clear();
        return;
      case CURSOR_POSITION:
        out_(Event::CursorPosition(pending_, output.cursor_x, output.cursor_y));
        pending_.clear();
        return;
    }
  }

  Output Parse() {
    if (!Eat()) {
      return UNCOMPLETED;
    }
    if (Current() == '\x1B') {
      return ParseESC();
    }
    if (Current() < 32) {
      return SPECIAL;
    }
    if (Current() == 127) {
      return SPECIAL;
    }
    return ParseUTF8();
  }

  Output ParseUTF8() {
    unsigned char head = Current();
    unsigned char selector = 0b1000'0000;
    unsigned char mask = selector;
    unsigned int first_zero = 8;
    for (unsigned int i = 0; i < 8; ++i) {
      mask |= selector;
      if (!(head & selector)) {
        first_zero = i;
        break;
      }
      selector >>= 1U;
    }
    uint32_t value = uint32_t(head & ~mask);
    if (first_zero == 1 || first_zero >= 5) {
      return DROP;
    }
    for (unsigned int i = 2; i <= first_zero; ++i) {
      if (!Eat()) {
        return UNCOMPLETED;
      }
      head = Current();
      if ((head & 0b1100'0000) != 0b1000'0000) {
        return DROP;
      }
      value <<= 6;
      value += head & 0b0011'1111;
    }
    int extra_byte = 0;
    if (value <= 0b000'0000'0111'1111) {
      extra_byte = 0;
    } else if (value <= 0b000'0111'1111'1111) {
      extra_byte = 1;
    } else if (value <= 0b1111'1111'1111'1111) {
      extra_byte = 2;
    } else if (value <= 0b1'0000'1111'1111'1111'1111) {
      extra_byte = 3;
    } else {
      return DROP;
    }
    if (extra_byte != position_) {
      return DROP;
    }
    return CHARACTER;
  }

  Output ParseESC() {
    if (!Eat()) {
      return UNCOMPLETED;
    }
    switch (Current()) {
      case 'P':
        return ParseDCS();
      case '[':
        return ParseCSI();
      case ']':
        return ParseOSC();
      case ' ':
      case '#':
      case '%':
      case '(':
      case ')':
      case '*':
      case '+':
      case 'O':
      case 'N':
        if (!Eat()) {
          return UNCOMPLETED;
        }
        return SPECIAL;
      default:
        return SPECIAL;
    }
  }

  Output ParseDCS() {
    while (true) {
      if (!Eat()) {
        return UNCOMPLETED;
      }
      if (Current() != '\x1B') {
        continue;
      }
      if (!Eat()) {
        return UNCOMPLETED;
      }
      if (Current() != '\\') {
        continue;
      }
      return DROP;
    }
  }

  Output ParseOSC() {
    while (true) {
      if (!Eat()) {
        return UNCOMPLETED;
      }
      if (Current() != '\x1B') {
        continue;
      }
      if (!Eat()) {
        return UNCOMPLETED;
      }
      if (Current() != '\\') {
        continue;
      }
      return SPECIAL;
    }
  }

  Output ParseCSI() {
    bool altered = false;
    int argument = 0;
    std::vector<int> arguments;
    while (true) {
      if (!Eat()) {
        return UNCOMPLETED;
      }
      if (Current() == '<') {
        altered = true;
        continue;
      }
      if (Current() >= '0' && Current() <= '9') {
        argument *= 10;
        argument += Current() - '0';
        continue;
      }
      if (Current() == ';') {
        arguments.push_back(argument);
        argument = 0;
        continue;
      }
      if (Current() >= '@' && Current() <= '~' && Current() != '<' &&
          Current() != '[') {
        arguments.push_back(argument);
        argument = 0;
        switch (Current()) {
          case 'M':
            return ParseMouse(altered, true, arguments);
          case 'm':
            return ParseMouse(altered, false, arguments);
          case 'R':
            return ParseCursorPosition(arguments);
          default:
            return SPECIAL;
        }
      }
      if (Current() == '\x1B') {
        return SPECIAL;
      }
    }
  }

  Output ParseMouse(bool /*altered*/, bool pressed,
                    const std::vector<int>& arguments) {
    if (arguments.size() != 3) {
      return SPECIAL;
    }
    Output output(MOUSE);
    const int button = arguments[0] & (1 + 2);
    const bool is_shift = arguments[0] & 4;
    const bool is_meta = arguments[0] & 8;
    const bool is_control = arguments[0] & 16;
    const bool is_move = arguments[0] & 32;
    const bool is_wheel = arguments[0] & 64;
    output.mouse.motion = is_move   ? Mouse::Moved
                          : pressed ? Mouse::Pressed
                                    : Mouse::Released;
    output.mouse.button = is_wheel ? Mouse::Button(Mouse::WheelUp + button)
                                   : Mouse::Button(button);
    output.mouse.shift = is_shift;
    output.mouse.meta = is_meta;
    output.mouse.control = is_control;
    output.mouse.x = arguments[1];
    output.mouse.y = arguments[2];
    return output;
  }

  Output ParseCursorPosition(const std::vector<int>& arguments) {
    if (arguments.size() != 2) {
      return SPECIAL;
    }
    Output output(CURSOR_POSITION);
    output.cursor_y = arguments[0];
    output.cursor_x = arguments[1];
    return output;
  }

  std::function<void(Event)> out_;
  std::string pending_;
  int position_ = -1;
  int timeout_ = 0;
};

termios g_saved_termios;
bool g_termios_saved = false;
int g_termios_fd = -1;

}  // namespace

ScreenInteractive::ScreenInteractive(Dimension dimension)
    : Screen(0, 0), dimension_(dimension) {
  use_alternative_screen_ = dimension == Dimension::Fullscreen;
}

ScreenInteractive ScreenInteractive::FitComponent() {
  return ScreenInteractive(Dimension::FitComponent);
}

ScreenInteractive ScreenInteractive::Fullscreen() {
  return ScreenInteractive(Dimension::Fullscreen);
}

void ScreenInteractive::Write(const std::string& s) { out_ += s; }

void ScreenInteractive::Flush() {
  out_ += '\0';
  size_t written = 0;
  while (written < out_.size()) {
    ssize_t r = write(STDOUT_FILENO, out_.data() + written,
                      out_.size() - written);
    if (r < 0) {
      if (errno == EINTR || errno == EAGAIN) {
        continue;
      }
      break;
    }
    written += static_cast<size_t>(r);
  }
  out_.clear();
}

void ScreenInteractive::Exit() { quit_ = true; }

void ScreenInteractive::PostEvent(Event event) {
  pending_events_.push_back(std::move(event));
}

CapturedMouse ScreenInteractive::CaptureMouse() {
  if (mouse_captured_) {
    return nullptr;
  }
  mouse_captured_ = true;
  return std::make_unique<CapturedMouseImpl>(
      [this] { mouse_captured_ = false; });
}

void ScreenInteractive::Install() {
  frame_valid_ = false;
  Flush();

  Write("\x1BP$q q\x1B\\");

  if (!isatty(STDIN_FILENO)) {
    int fd = open("/dev/tty", O_RDONLY);
    if (fd >= 0) {
      input_fd_ = fd;
      opened_tty_ = true;
    }
  } else {
    input_fd_ = STDIN_FILENO;
  }

  if (pipe(g_signal_pipe) == 0) {
    fcntl(g_signal_pipe[0], F_SETFL, O_NONBLOCK);
    fcntl(g_signal_pipe[1], F_SETFL, O_NONBLOCK);
  }
  struct sigaction sa {};
  sa.sa_handler = OnSignal;
  sigemptyset(&sa.sa_mask);
  sa.sa_flags = 0;
  for (int s : {SIGWINCH, SIGTERM, SIGINT, SIGHUP, SIGQUIT}) {
    sigaction(s, &sa, nullptr);
  }

  termios terminal{};
  if (tcgetattr(input_fd_, &terminal) == 0) {
    g_saved_termios = terminal;
    g_termios_saved = true;
    g_termios_fd = input_fd_;
    terminal.c_lflag &= ~ICANON;
    terminal.c_lflag &= ~ECHO;
    terminal.c_cc[VMIN] = 0;
    terminal.c_cc[VTIME] = 0;
    tcsetattr(input_fd_, TCSANOW, &terminal);
  }

  if (use_alternative_screen_) {
    Write("\x1B[?1049h");
  }
  Write("\x1B[?7l");
  Write("\x1B[?1000h");
  Write("\x1B[?1003h");
  Write("\x1B[?1015h");
  Write("\x1B[?1006h");
  Flush();
  quit_ = false;
}

void ScreenInteractive::Uninstall() {
  Write("\x1B[?1006l");
  Write("\x1B[?1015l");
  Write("\x1B[?1003l");
  Write("\x1B[?1000l");
  Write("\x1B[?7h");
  if (use_alternative_screen_) {
    Write("\x1B[?1049l");
  }
  if (g_termios_saved) {
    tcsetattr(g_termios_fd, TCSANOW, &g_saved_termios);
  }
  Write("\x1B[?25h");
  Write("\x1B[1 q");
  Flush();
  if (opened_tty_) {
    close(input_fd_);
  }
}

void ScreenInteractive::ResetCursorPosition() {
  Write(reset_cursor_position_);
  reset_cursor_position_.clear();
}

std::string ScreenInteractive::ResetPosition(bool clear) const {
  std::string ss;
  if (clear) {
    ss += "\r";
    ss += "\x1B[2K";
    for (int y = 1; y < dimy_; ++y) {
      ss += "\x1B[1A";
      ss += "\x1B[2K";
    }
  } else {
    ss += "\r";
    for (int y = 1; y < dimy_; ++y) {
      ss += "\x1B[1A";
    }
  }
  return ss;
}

void ScreenInteractive::Draw(Component component) {
  if (!component) {
    return;
  }
  auto document = component->Render();
  int dimx = 0;
  int dimy = 0;
  auto terminal = TerminalSize();
  document->ComputeRequirement();
  switch (dimension_) {
    case Dimension::Fullscreen:
      dimx = terminal.dimx;
      dimy = terminal.dimy;
      break;
    case Dimension::FitComponent:
      dimx = std::max(0, std::min(document->requirement().min_x, terminal.dimx));
      dimy = std::max(0, std::min(document->requirement().min_y, terminal.dimy));
      break;
  }

  const bool resized = frame_count_ == 0 || (dimx != dimx_) || (dimy != dimy_);
  ResetCursorPosition();
  Write(ResetPosition(resized));

  if ((dimx < dimx_) && !use_alternative_screen_) {
    Write("\033[J");
    Write("\033[H");
  }

  if (resized) {
    Resize(dimx, dimy);
  }

  static int i = -3;
  ++i;
  if (!use_alternative_screen_ && (previous_frame_resized_ || i % 40 == 0)) {
    Write("\x1B[6n");
  }
  previous_frame_resized_ = resized;

  Selection selection = selection_data_.empty
                            ? Selection()
                            : Selection(selection_data_.start_x,
                                        selection_data_.start_y,
                                        selection_data_.end_x,
                                        selection_data_.end_y);
  jt::Render(*this, document.get(), selection);

  {
    const int dx = dimx_ - 1 - cursor.x + int(dimx_ != terminal.dimx);
    const int dy = dimy_ - 1 - cursor.y;
    set_cursor_position_.clear();
    reset_cursor_position_.clear();
    if (dy != 0) {
      set_cursor_position_ += "\x1B[" + std::to_string(dy) + "A";
      reset_cursor_position_ += "\x1B[" + std::to_string(dy) + "B";
    }
    if (dx != 0) {
      set_cursor_position_ += "\x1B[" + std::to_string(dx) + "D";
      reset_cursor_position_ += "\x1B[" + std::to_string(dx) + "C";
    }
    set_cursor_position_ += "\033[?25l";
  }

  Write(ToString());
  Write(set_cursor_position_);
  Flush();
  Clear();
  frame_valid_ = true;
  frame_count_++;
}

bool ScreenInteractive::HandleSelection(bool handled, Event event) {
  if (handled) {
    selection_pending_ = nullptr;
    selection_data_.empty = true;
    return true;
  }
  if (!event.is_mouse()) {
    return false;
  }
  auto& mouse = event.mouse();
  if (mouse.button != Mouse::Left) {
    return false;
  }
  if (mouse.motion == Mouse::Pressed) {
    selection_pending_ = CaptureMouse();
    selection_data_.start_x = mouse.x;
    selection_data_.start_y = mouse.y;
    selection_data_.end_x = mouse.x;
    selection_data_.end_y = mouse.y;
    return false;
  }
  if (!selection_pending_) {
    return false;
  }
  if (mouse.motion == Mouse::Moved) {
    if ((mouse.x != selection_data_.end_x) ||
        (mouse.y != selection_data_.end_y)) {
      selection_data_.end_x = mouse.x;
      selection_data_.end_y = mouse.y;
      selection_data_.empty = false;
    }
    return true;
  }
  if (mouse.motion == Mouse::Released) {
    selection_pending_ = nullptr;
    selection_data_.end_x = mouse.x;
    selection_data_.end_y = mouse.y;
    selection_data_.empty = false;
    return true;
  }
  return false;
}

void ScreenInteractive::HandleEvent(Component& component, Event event) {
  if (event.is_cursor_position()) {
    cursor_x_ = event.cursor_x();
    cursor_y_ = event.cursor_y();
    return;
  }
  if (event.is_mouse()) {
    event.mouse().x -= cursor_x_;
    event.mouse().y -= cursor_y_;
  }
  event.screen_ = this;
  bool handled = component->OnEvent(event);
  handled = HandleSelection(handled, event);
  if (event == Event::CtrlC) {
    quit_ = true;
  }
  frame_valid_ = false;
}

void ScreenInteractive::Loop(Component component) {
  Install();

  InputParser parser([this](Event e) { pending_events_.push_back(std::move(e)); });

  Draw(component);

  auto last_read = std::chrono::steady_clock::now();
  while (!quit_) {
    // Process pending events first.
    while (!pending_events_.empty() && !quit_) {
      Event e = pending_events_.front();
      pending_events_.pop_front();
      HandleEvent(component, e);
    }
    if (quit_) {
      break;
    }
    if (g_signal_exit) {
      break;
    }
    if (!frame_valid_) {
      Draw(component);
    }

    pollfd fds[2];
    fds[0].fd = input_fd_;
    fds[0].events = POLLIN;
    fds[0].revents = 0;
    fds[1].fd = g_signal_pipe[0];
    fds[1].events = POLLIN;
    fds[1].revents = 0;
    int timeout = parser.HasPending() ? 20 : -1;
    int r = poll(fds, g_signal_pipe[0] >= 0 ? 2 : 1, timeout);
    if (r < 0) {
      if (errno == EINTR) {
        continue;
      }
      break;
    }
    if (g_signal_pipe[0] >= 0 && (fds[1].revents & POLLIN)) {
      char buf[64];
      while (read(g_signal_pipe[0], buf, sizeof(buf)) > 0) {
      }
    }
    if (g_signal_exit) {
      break;
    }
    if (g_signal_winch) {
      g_signal_winch = 0;
      pending_events_.push_back(Event::Special(std::string(1, '\0')));
    }
    if (fds[0].revents & POLLIN) {
      char buf[256];
      ssize_t n = read(input_fd_, buf, sizeof(buf));
      if (n > 0) {
        for (ssize_t k = 0; k < n; ++k) {
          parser.Add(buf[k]);
        }
        last_read = std::chrono::steady_clock::now();
      } else if (n == 0) {
        // EOF on the terminal: avoid spinning.
        usleep(20000);
      }
    } else if (fds[0].revents & (POLLHUP | POLLERR | POLLNVAL)) {
      break;
    } else if (r == 0) {
      auto now = std::chrono::steady_clock::now();
      int ms = static_cast<int>(
          std::chrono::duration_cast<std::chrono::milliseconds>(now - last_read)
              .count());
      last_read = now;
      parser.Timeout(ms);
    }
  }

  // Put cursor position at the end of the drawing.
  ResetCursorPosition();
  Uninstall();
  Write("\r");
  if (!use_alternative_screen_) {
    Write("\n");
  }
  size_t written = 0;
  while (written < out_.size()) {
    ssize_t w = write(STDOUT_FILENO, out_.data() + written, out_.size() - written);
    if (w <= 0) {
      break;
    }
    written += static_cast<size_t>(w);
  }
  out_.clear();
  if (g_signal_exit) {
    int s = g_signal_exit;
    signal(s, SIG_DFL);
    raise(s);
  }
}

