// ---------------------------------------------------------------------------
// Expander: tracks the expanded/collapsed state of every collapsible node, so
// that whole levels can be expanded or collapsed at once.
class ExpanderImpl;
using Expander = std::unique_ptr<ExpanderImpl>;

class ExpanderImpl {
 public:
  static Expander Root() {
    auto root = std::make_unique<ExpanderImpl>();
    root->expanded = true;
    return root;
  }

  ~ExpanderImpl() {
    for (ExpanderImpl* child : children_) {
      child->parent_ = nullptr;
    }
    if (parent_) {
      auto& siblings = parent_->children_;
      for (auto it = siblings.begin(); it != siblings.end(); ++it) {
        if (*it == this) {
          siblings.erase(it);
          break;
        }
      }
    }
  }

  Expander Child() {
    auto child = std::make_unique<ExpanderImpl>();
    child->parent_ = this;
    children_.push_back(child.get());
    return child;
  }

  // Expand the shallowest collapsed nodes of this subtree.
  void Expand() {
    const int level = MinLevel();
    if (level >= kInfinity) {
      return;
    }
    ExpandLevel(level);
  }

  // Collapse the deepest expanded nodes of this subtree. Returns false when
  // nothing was expanded.
  bool Collapse() {
    const int level = MaxLevel();
    if (level < 0) {
      return false;
    }
    CollapseLevel(level);
    return true;
  }

  bool expanded = false;

 private:
  static constexpr int kInfinity = INT_MAX / 4;

  int MinLevel() const {
    if (!expanded) {
      return 0;
    }
    int level = kInfinity;
    for (const ExpanderImpl* child : children_) {
      level = std::min(level, child->MinLevel() + 1);
    }
    return level;
  }

  int MaxLevel() const {
    if (!expanded) {
      return -1;
    }
    int level = 0;
    for (const ExpanderImpl* child : children_) {
      level = std::max(level, child->MaxLevel() + 1);
    }
    return level;
  }

  void ExpandLevel(int level) {
    if (level == 0) {
      expanded = true;
      return;
    }
    if (!expanded) {
      return;
    }
    for (ExpanderImpl* child : children_) {
      child->ExpandLevel(level - 1);
    }
  }

  void CollapseLevel(int level) {
    if (level <= 0) {
      expanded = false;
    }
    for (ExpanderImpl* child : children_) {
      child->CollapseLevel(level - 1);
    }
  }

  ExpanderImpl* parent_ = nullptr;
  std::vector<ExpanderImpl*> children_;
};

