// Generic helpers.

Component Empty() {
  return Renderer([] { return emptyElement(); });
}

Component Maybe(Component child, std::function<bool()> show) {
  class Impl : public ComponentBase {
   public:
    explicit Impl(std::function<bool()> show) : show_(std::move(show)) {}

   private:
    Element OnRender() override {
      return show_() ? ComponentBase::OnRender() : std::make_shared<Node>();
    }
    bool Focusable() const override {
      return show_() && ComponentBase::Focusable();
    }
    bool OnEvent(Event event) override {
      return show_() && ComponentBase::OnEvent(event);
    }
    std::function<bool()> show_;
  };
  auto maybe = Make<Impl>(std::move(show));
  maybe->Add(std::move(child));
  return maybe;
}

Component Indentation(Component child) {
  return Renderer(child, [child] {
    return hbox({
        text("  "),
        child->Render(),
    });
  });
}

Component FakeHorizontal(Component a, Component b) {
  auto c = Container::Vertical({a, b});
  c->SetActiveChild(b);
  return Renderer(c, [a, b] {
    return hbox({
        a->Render(),
        b->Render(),
    });
  });
}

enum class ButtonStyle { Toggle, View };

class ButtonImpl : public ComponentBase {
 public:
  ButtonImpl(std::function<std::string()> label, std::function<void()> on_click,
             ButtonStyle style)
      : label_(std::move(label)), on_click_(std::move(on_click)), style_(style) {}

  Element OnRender() override {
    const bool focused = Focused();
    const bool active = focused || mouse_hover_;
    Element element = text(label_());
    if (style_ == ButtonStyle::Toggle) {
      element = active ? inverted(element) : bold(element);
    } else {
      element = color(Color::GrayDark, element);
      if (active) {
        element = inverted(element);
      }
    }
    if (focused) {
      element = focus(element);
    }
    return reflect(element, box_);
  }

  bool OnEvent(Event event) override {
    if (event.is_mouse()) {
      return OnMouseEvent(event);
    }
    if (event == Event::Return || event == Event::Character(" ")) {
      on_click_();
      return true;
    }
    return false;
  }

  bool Focusable() const override { return true; }

 private:
  bool OnMouseEvent(Event event) {
    mouse_hover_ = box_.Contain(event.mouse().x, event.mouse().y) &&
                   CaptureMouse(event);
    if (!mouse_hover_) {
      return false;
    }
    if (event.mouse().button == Mouse::Left &&
        event.mouse().motion == Mouse::Pressed) {
      on_click_();
      return true;
    }
    return false;
  }

  std::function<std::string()> label_;
  std::function<void()> on_click_;
  ButtonStyle style_;
  bool mouse_hover_ = false;
  Box box_;
};

Component MyButton(std::function<std::string()> label,
                   std::function<void()> on_click, ButtonStyle style) {
  return Make<ButtonImpl>(std::move(label), std::move(on_click), style);
}

// ---------------------------------------------------------------------------
// JSON components.

Component From(const Json& json, bool is_last, int depth, Expander& expander);
Component FromArrayAny(Component prefix, const Json& json, bool is_last,
                       int depth, Expander& expander);
Component FromObject(Component prefix, const Json& json, bool is_last,
                     int depth, Expander& expander);

Component Basic(std::string value, Color c, bool is_last) {
  return Renderer([value, c, is_last](bool focused) {
    Element element = paragraph(value) | color(c);
    if (focused) {
      element = focus(inverted(element));
    }
    if (!is_last) {
      element = hbox({element, text(",")});
    }
    return element;
  });
}

Component FromString(const Json& json, bool is_last) {
  return Basic("\"" + json.string_value + "\"", Color::GreenLight, is_last);
}

Component FromNumber(const Json& json, bool is_last) {
  return Basic(json.DumpNumber(), Color::CyanLight, is_last);
}

Component FromBoolean(const Json& json, bool is_last) {
  return Basic(json.boolean_value ? "true" : "false", Color::YellowLight,
               is_last);
}

Component FromNull(bool is_last) {
  return Basic("null", Color::RedLight, is_last);
}

Component KeyPrefix(const std::string& key) {
  return Renderer([key] {
    return hbox({
        text("\"" + key + "\"") | color(Color::BlueLight),
        text(": "),
    });
  });
}

Component FromKeyValue(const std::string& key, const Json& value, bool is_last,
                       int depth, Expander& expander) {
  Component prefix = KeyPrefix(key);
  if (value.is_object()) {
    return FromObject(prefix, value, is_last, depth, expander);
  }
  if (value.is_array()) {
    return FromArrayAny(prefix, value, is_last, depth, expander);
  }
  Component child = From(value, is_last, depth, expander);
  return FakeHorizontal(prefix, child);
}

// Base for collapsible containers (objects and arrays).
class CollapsibleBase : public ComponentBase {
 protected:
  bool OnEvent(Event event) override {
    if (ComponentBase::OnEvent(event)) {
      return true;
    }
    if (event == Event::Character("+")) {
      expander_->Expand();
      return true;
    }
    if (event == Event::Character("-")) {
      return expander_->Collapse();
    }
    return false;
  }

  Expander expander_;
};

class ObjectImpl : public CollapsibleBase {
 public:
  ObjectImpl(Component prefix, const Json& json, bool is_last, int depth,
             Expander& expander)
      : is_last_(is_last) {
    expander_ = expander->Child();
    expander_->expanded = depth < 2;

    auto children = Container::Vertical({});
    size_t remaining = json.object_value.size();
    for (const auto& it : json.object_value) {
      const bool is_children_last = --remaining == 0;
      children->Add(Indentation(
          FromKeyValue(it.first, it.second, is_children_last, depth + 1,
                       expander_)));
    }
    children->Add(Renderer([is_last] { return text(is_last ? "}" : "},"); }));

    auto toggle = MyButton(
        [this] {
          if (expander_->expanded) {
            return std::string("{");
          }
          return std::string(is_last_ ? "{...}" : "{...},");
        },
        [this] { expander_->expanded = !expander_->expanded; },
        ButtonStyle::Toggle);

    header_ = FakeHorizontal(prefix, toggle);
    children_container_ = children;
    Add(Container::Vertical({
        header_,
        Maybe(children, [this] { return expander_->expanded; }),
    }));
  }

  Element OnRender() override {
    if (expander_->expanded) {
      return vbox({header_->Render(), children_container_->Render()});
    }
    return header_->Render();
  }

 private:
  bool is_last_;
  Component header_;
  Component children_container_;
};

Component FromObject(Component prefix, const Json& json, bool is_last,
                     int depth, Expander& expander) {
  return Make<ObjectImpl>(prefix, json, is_last, depth, expander);
}

bool IsSuitableForTableView(const Json& json) {
  if (!json.is_array() || json.array_value.size() < 2) {
    return false;
  }
  for (const auto& element : json.array_value) {
    if (!element.is_object()) {
      return false;
    }
  }
  return true;
}

class ArrayViewImpl : public CollapsibleBase {
 public:
  ArrayViewImpl(Component prefix, const Json& json, bool is_last, int depth,
                Expander& expander, std::function<void()> on_table_view)
      : is_last_(is_last) {
    expander_ = expander->Child();
    expander_->expanded = depth < 1;

    auto children = Container::Vertical({});
    const size_t size = json.array_value.size();
    for (size_t i = 0; i < size; ++i) {
      const bool is_children_last = i + 1 == size;
      children->Add(Indentation(
          From(json.array_value[i], is_children_last, depth + 1, expander_)));
    }
    children->Add(Renderer([is_last] { return text(is_last ? "]" : "],"); }));

    auto toggle = MyButton(
        [this] {
          if (expander_->expanded) {
            return std::string("[");
          }
          return std::string(is_last_ ? "[...]" : "[...],");
        },
        [this] { expander_->expanded = !expander_->expanded; },
        ButtonStyle::Toggle);

    Component line;
    if (IsSuitableForTableView(json)) {
      view_button_ = MyButton([] { return std::string("(table view)"); },
                              std::move(on_table_view), ButtonStyle::View);
      auto inner = Container::Horizontal({toggle, view_button_});
      Component view_button = view_button_;
      line = Renderer(inner, [toggle, view_button] {
        return hbox({
            toggle->Render(),
            text("   "),
            view_button->Render(),
        });
      });
    } else {
      line = toggle;
    }

    header_ = FakeHorizontal(prefix, line);
    children_container_ = children;
    Add(Container::Vertical({
        header_,
        Maybe(children, [this] { return expander_->expanded; }),
    }));
  }

  Element OnRender() override {
    if (expander_->expanded) {
      return vbox({header_->Render(), children_container_->Render()});
    }
    return header_->Render();
  }

  Component view_button_;

 private:
  bool is_last_;
  Component header_;
  Component children_container_;
};

class TableViewImpl : public ComponentBase {
 public:
  TableViewImpl(Component prefix, const Json& json, int depth,
                Expander& expander, std::function<void()> on_array_view) {
    view_button_ = MyButton([] { return std::string("(array view)"); },
                            std::move(on_array_view), ButtonStyle::View);
    header_ = FakeHorizontal(prefix, view_button_);

    std::map<std::string, int> column_index;
    for (const auto& row : json.array_value) {
      for (const auto& it : row.object_value) {
        if (column_index.count(it.first) == 0) {
          column_index[it.first] = static_cast<int>(columns_.size());
          columns_.push_back(it.first);
        }
      }
    }

    auto rows = Container::Vertical({});
    for (const auto& row : json.array_value) {
      auto line = Container::Horizontal({});
      std::vector<Component> cells(columns_.size());
      for (const auto& it : row.object_value) {
        Component cell = From(it.second, true, depth + 1, expander);
        cells[column_index[it.first]] = cell;
      }
      for (auto& cell : cells) {
        if (cell) {
          line->Add(cell);
        }
      }
      rows->Add(line);
      cells_.push_back(std::move(cells));
    }
    Add(Container::Vertical({header_, rows}));
  }

  Element OnRender() override {
    std::vector<Elements> data;
    Elements header_row;
    header_row.push_back(text(""));
    for (const auto& column : columns_) {
      header_row.push_back(text(column));
    }
    data.push_back(std::move(header_row));
    for (size_t i = 0; i < cells_.size(); ++i) {
      Elements line;
      line.push_back(text(std::to_string(i)));
      for (auto& cell : cells_[i]) {
        line.push_back(cell ? cell->Render() : text(""));
      }
      data.push_back(std::move(line));
    }

    Table table(std::move(data));
    table.SelectColumns(1, -1).Border(LIGHT);
    table.SelectColumns(1, -1).SeparatorVertical(LIGHT);
    table.SelectRectangle(1, -1, 0, 0).Border(HEAVY);
    table.SelectRectangle(1, -1, 0, 0).SeparatorVertical(HEAVY);
    table.SelectColumn(0).DecorateCells(color(Color::GrayDark));

    return vbox({
        header_->Render(),
        table.Render(),
    });
  }

  Component view_button_;

 private:
  Component header_;
  std::vector<std::string> columns_;
  std::vector<std::vector<Component>> cells_;
};

class ArrayAnyImpl : public ComponentBase {
 public:
  ArrayAnyImpl(Component prefix, const Json& json, bool is_last, int depth,
               Expander& expander)
      : prefix_(std::move(prefix)),
        json_(json),
        is_last_(is_last),
        depth_(depth),
        expander_(expander) {
    Refresh();
  }

  bool OnEvent(Event event) override {
    const bool handled = ComponentBase::OnEvent(event);
    if (switch_requested_) {
      switch_requested_ = false;
      table_view_ = !table_view_;
      Refresh();
      if (view_button_) {
        view_button_->TakeFocus();
      }
    }
    return handled;
  }

 private:
  void Refresh() {
    DetachAllChildren();
    auto request = [this] { switch_requested_ = true; };
    if (table_view_) {
      auto view = Make<TableViewImpl>(prefix_, json_, depth_, expander_, request);
      view_button_ = view->view_button_;
      Add(view);
    } else {
      auto view = Make<ArrayViewImpl>(prefix_, json_, is_last_, depth_,
                                      expander_, request);
      view_button_ = view->view_button_;
      Add(view);
    }
  }

  Component prefix_;
  const Json& json_;
  bool is_last_;
  int depth_;
  Expander& expander_;
  bool table_view_ = false;
  bool switch_requested_ = false;
  Component view_button_;
};

Component FromArrayAny(Component prefix, const Json& json, bool is_last,
                       int depth, Expander& expander) {
  return Make<ArrayAnyImpl>(prefix, json, is_last, depth, expander);
}

Component From(const Json& json, bool is_last, int depth, Expander& expander) {
  if (json.is_object()) {
    return FromObject(Empty(), json, is_last, depth, expander);
  }
  if (json.is_array()) {
    return FromArrayAny(Empty(), json, is_last, depth, expander);
  }
  if (json.is_string()) {
    return FromString(json, is_last);
  }
  if (json.is_number()) {
    return FromNumber(json, is_last);
  }
  if (json.is_boolean()) {
    return FromBoolean(json, is_last);
  }
  return FromNull(is_last);
}

void DisplayMainUI(const Json& json, bool fullscreen) {
  auto screen = fullscreen ? ScreenInteractive::Fullscreen()
                           : ScreenInteractive::FitComponent();
  Expander expander = ExpanderImpl::Root();
  Component component = From(json, /*is_last=*/true, /*depth=*/0, expander);

  // Wrap it inside a frame, to allow scrolling.
  component =
      Renderer(component, [component] { return yframe(component->Render()); });

  Component inner = component;
  Event previous_event;
  component = CatchEvent(component, [&](Event event) {
    const bool is_gg = event == Event::Character("g") &&
                       previous_event == Event::Character("g");
    previous_event = event;

    // Quit using 'q' or ESC.
    if (event == Event::Character("q") || event == Event::Escape) {
      screen.Exit();
      return true;
    }

    // Convert the mouse wheel into their corresponding up/down events.
    if (event.is_mouse()) {
      if (event.mouse().button == Mouse::WheelDown) {
        screen.PostEvent(Event::ArrowDown);
        return true;
      }
      if (event.mouse().button == Mouse::WheelUp) {
        screen.PostEvent(Event::ArrowUp);
        return true;
      }
      return false;
    }

    // Top / bottom.
    if (event == Event::Character("G")) {
      for (int i = 0; i < 1000000; ++i) {
        Event up = Event::ArrowUp;
        up.screen_ = event.screen_;
        if (!inner->OnEvent(up)) {
          break;
        }
      }
      return true;
    }
    if (is_gg) {
      for (int i = 0; i < 1000000; ++i) {
        Event down = Event::ArrowDown;
        down.screen_ = event.screen_;
        if (!inner->OnEvent(down)) {
          break;
        }
      }
      return true;
    }
    return false;
  });

  screen.Loop(component);
}

// ---------------------------------------------------------------------------
// Key bindings.
void DisplayKeyBindings() {
  auto lines = [](std::vector<std::string> list) {
    Elements out;
    for (auto& it : list) {
      out.push_back(text(it));
    }
    return vbox(std::move(out));
  };

  std::vector<Elements> data = {
      {text("keys") | color(Color::Cyan), text("action") | color(Color::Cyan)},
      {text("Navigate"), lines({"← ↑ ↓ →", "h j k l", "Mouse::WheelUp",
                                "Mouse::WheelDown"})},
      {text("Toggle"), lines({"enter", "Mouse::Left"})},
      {lines({"Deep", " - Expand", " - Collapse"}), lines({"", "+", "-"})},
      {text("Exit"), lines({"Escape", "q"})},
      {lines({"Navigate", " - first", " - last", " - top", " - bottom"}),
       lines({"", "page-up", "page-down", "gg", "G"})},
  };

  Table table(std::move(data));
  table.SelectAll().Border(LIGHT);
  table.SelectAll().Separator(LIGHT);
  Element document = table.Render();

  // Compute the dimensions: fit the document, without exceeding the terminal.
  winsize w{};
  int term_x = 80;
  int term_y = 24;
  if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &w) >= 0 && w.ws_col != 0 &&
      w.ws_row != 0) {
    term_x = w.ws_col;
    term_y = w.ws_row;
  }
  document->ComputeRequirement();
  int dimx = std::min(document->requirement().min_x, term_x);
  int dimy = std::min(document->requirement().min_y, term_y);

  // Vertical squeeze: content rows are dropped from the bottom first.
  std::vector<Elements> unused;
  (void)unused;
  Screen screen(dimx, dimy);
  Render(screen, document);
  std::cout << screen.ToString() << '\0' << std::flush;
  std::cout << std::endl;
}

const char* kHelp =
    "  json-tui {OPTIONS} [file]\n"
    "\n"
    "    A JSON terminal UI\n"
    "\n"
    "  OPTIONS:\n"
    "\n"
    "      file                              A JSON file. Omit to read from "
    "stdin.\n"
    "      -h, --help                        Display this help menu.\n"
    "      -v, --version                     Print version.\n"
    "      -k, --key, --keybinding           Display key binding.\n"
    "      -f, --fullscreen                  Display the JSON in fullscreen, "
    "in an\n"
    "                                        alternate buffer\n"
    "      \"--\" can be used to terminate flag options and force all "
    "following\n"
    "      arguments to be treated as positional options\n"
    "\n"
    "    If no file is given, json-tui reads JSON from the standard input\n"
    "    Please report bugs to:https://github.com/ArthurSonzogni/json-tui/"
    "issues\n";

}  // namespace

int main(int argc, char** argv) {
  bool help = false;
  bool version = false;
  bool keybinding = false;
  bool fullscreen = false;
  bool has_file = false;
  std::string file;
  bool error = false;
  bool only_positional = false;

  for (int i = 1; i < argc; ++i) {
    std::string arg = argv[i];
    if (only_positional) {
      if (has_file) {
        error = true;
        break;
      }
      has_file = true;
      file = arg;
      continue;
    }
    if (arg == "--") {
      only_positional = true;
      continue;
    }
    if (arg.size() > 2 && arg[0] == '-' && arg[1] == '-') {
      std::string name = arg.substr(2);
      if (name == "help") {
        help = true;
      } else if (name == "version") {
        version = true;
      } else if (name == "key" || name == "keybinding") {
        keybinding = true;
      } else if (name == "fullscreen") {
        fullscreen = true;
      } else {
        error = true;
        break;
      }
      continue;
    }
    if (arg.size() > 1 && arg[0] == '-') {
      for (size_t k = 1; k < arg.size(); ++k) {
        switch (arg[k]) {
          case 'h': help = true; break;
          case 'v': version = true; break;
          case 'k': keybinding = true; break;
          case 'f': fullscreen = true; break;
          default: error = true; break;
        }
        if (error) {
          break;
        }
      }
      if (error) {
        break;
      }
      continue;
    }
    if (has_file) {
      error = true;
      break;
    }
    has_file = true;
    file = arg;
  }

  if (error) {
    std::cerr << "Invalid arguments" << std::endl;
    return 1;
  }
  if (help) {
    std::cout << kHelp;
    return 0;
  }
  if (version) {
    std::cout << "1.4.1" << std::endl;
    return 0;
  }
  if (keybinding) {
    DisplayKeyBindings();
    return 0;
  }

  std::string input;
  if (!has_file) {
    std::cout << "Reading from stdin..." << std::flush;
    std::stringstream ss;
    ss << std::cin.rdbuf();
    input = ss.str();
  } else {
    std::ifstream stream(file, std::ios::binary);
    if (!stream.is_open()) {
      std::cerr << "Could not open file " << file << std::endl;
      return 1;
    }
    std::stringstream ss;
    ss << stream.rdbuf();
    input = ss.str();
  }

  Json json;
  std::string message;
  if (!ParseJson(input, json, message)) {
    std::cerr << std::endl;
    std::cerr << message << std::endl;
    return 1;
  }

  DisplayMainUI(json, fullscreen);
  return 0;
}
